1	package main
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"os"
9		"path/filepath"
10		"sort"
11		"strings"
12		"time"
13	)
14	
15	// 数据目录布局：
16	//
17	//	<dir>/state.json      全部业务数据（客户、用量、账单、封账状态）
18	//	<dir>/state.json.tmp  原子写入临时文件（保存后 rename 覆盖）
19	//
20	// 所有命令顺序运行，单次调用内完成“读入—修改—整体原子落盘”，
21	// 因此账单与封账状态在同一次保存中持久化，不会出现半写状态。
22	
23	const stateVersion = 1
24	
25	type customer struct {
26		ID     string `json:"id"`
27		Name   string `json:"name"`
28		Price  int64  `json:"price_fen"`         // 固定单价，非负整数分，创建后不可修改
29		PlanID string `json:"plan_id,omitempty"` // 绑定的阶梯计费方案标识；空表示固定单价客户，创建后不可变更
30	}
31	
32	// tier 是阶梯计费方案中的一档：Limit 为月累计数量上限（正整数），
33	// 仅最后一档无上限（Limit 为 0）；Price 为该档每单位价格（非负整数分）。
34	type tier struct {
35		Limit int64 `json:"limit"`     // 累计数量上限；0 表示无上限（仅最后一档）
36		Price int64 `json:"price_fen"` // 每单位价格，非负整数分，可升可降
37	}
38	
39	// plan 是按月累计用量的阶梯计费方案：标识唯一非空、名称非空、固定月费
40	// （非负整数分，省略视为 0）与至少一档有序阶梯；月费与规则创建后不可修改。
41	type plan struct {
42		ID         string `json:"id"`
43		Name       string `json:"name"`
44		MonthlyFee int64  `json:"monthly_fee_fen,omitempty"` // 固定月费，非负整数分；每账期收取一次整月，不按天折算
45		Tiers      []tier `json:"tiers"`                     // 至少一档；有限上限严格递增，最后一档无上限
46	}
47	
48	type usageRecord struct {
49		ID         string `json:"id"`
50		CustomerID string `json:"customer_id"`
51		Time       string `json:"time"` // RFC3339，保留原始输入用于去重判定
52		Quantity   int64  `json:"quantity"`
53	}
54	
55	// lineSegment 是阶梯计费下一条用量记录落入某一档的分段：数量与小计；
56	// 该档单价由账单保存的方案规则按档位序号取得。
57	type lineSegment struct {
58		Tier     int   `json:"tier"`     // 档位序号（0 起，对应账单保存的方案规则）
59		Quantity int64 `json:"quantity"` // 落入本档的数量
60		Fee      int64 `json:"fee_fen"`  // 本分段小计（数量 × 该档单价）
61	}
62	
63	// tierTotal 是阶梯账单中某一档的合计数量与金额（与 PlanTiers 顺序对齐）。
64	type tierTotal struct {
65		Quantity int64 `json:"quantity"`
66		Fee      int64 `json:"fee_fen"`
67	}
68	
69	type billLine struct {
70		UsageID  string        `json:"usage_id"`
71		Time     string        `json:"time"`
72		Quantity int64         `json:"quantity"`
73		LineFee  int64         `json:"line_fee_fen"`
74		Segments []lineSegment `json:"segments,omitempty"` // 阶梯账单：本条用量的跨档分段
75	}
76	
77	type bill struct {
78		ID         string      `json:"id"`
79		CustomerID string      `json:"customer_id"`
80		Month      string      `json:"month"`                 // YYYY-MM（UTC）
81		Pricing    string      `json:"pricing,omitempty"`     // 计价类型：空或 fixed 为固定单价；tiered 为阶梯计费
82		PlanID     string      `json:"plan_id,omitempty"`     // 阶梯账单：方案标识
83		PlanName   string      `json:"plan_name,omitempty"`   // 阶梯账单：方案名称（快照）
84		PlanTiers  []tier      `json:"plan_tiers,omitempty"`  // 阶梯账单：完整方案规则（快照）
85		TierTotals []tierTotal `json:"tier_totals,omitempty"` // 阶梯账单：各档实际数量与金额合计
86		// 阶梯账单：实际收取的固定月费快照（分），非负；按账期有效方案收取一次
87		// 整月，不计入总数量、各档金额或逐条小计。固定单价账单恒为 0。
88		MonthlyFee int64      `json:"monthly_fee_fen,omitempty"`
89		TotalQty   int64      `json:"total_quantity"`
90		UnitPrice  int64      `json:"unit_price_fen"` // 固定单价账单的单价；阶梯账单恒为 0（不伪造统一单价）
91		TotalFee   int64      `json:"total_fee_fen"`
92		Lines      []billLine `json:"lines"`
93		CreatedAt  string     `json:"created_at"`
94	}
95	
96	// adjustment 是对已结算账单的一次费用调整（正数补收、负数减免）。
97	// 记录一旦写入永不删除；撤销只是追加撤销信息，保留原记录。
98	type adjustment struct {
99		ID           string `json:"id"`
100		CustomerID   string `json:"customer_id"`
101		Month        string `json:"month"` // YYYY-MM（UTC），与所属账单一致
102		Amount       int64  `json:"amount_fen"`
103		Reason       string `json:"reason"`
104		Seq          int64  `json:"seq"` // 全局递增操作序号，决定历史展示顺序
105		CreatedAt    string `json:"created_at"`
106		Revoked      bool   `json:"revoked"`
107		RevokeReason string `json:"revoke_reason,omitempty"`
108		RevokeSeq    int64  `json:"revoke_seq,omitempty"`
109		RevokedAt    string `json:"revoked_at,omitempty"`
110	}
111	
112	// paymentAllocation 是一笔收款在某个已结算月份上的分配（正整数分）。
113	type paymentAllocation struct {
114		Month  string `json:"month"`      // YYYY-MM（UTC），须已有账单
115		Amount int64  `json:"amount_fen"` // 正整数分
116	}
117	
118	// payment 是一笔实收登记：同一客户的一笔汇款（总额 Total 分）按分配列表
119	// 计入一个或多个已结算月份；单账单收款视为只有一项分配的汇款。
120	// 记录一旦写入永不删除；撤销只是追加撤销信息，整笔撤销全部分配并保留
121	// 原记录，撤销后该笔不再计入实收，也不会因重放而恢复。
122	type payment struct {
123		ID          string              `json:"id"`
124		CustomerID  string              `json:"customer_id"`
125		Total       int64               `json:"total_fen"` // 收款总额，正整数分，等于分配合计
126		Note        string              `json:"note"`
127		Allocations []paymentAllocation `json:"allocations"` // 至少一项，月份不重复，按月份升序保存
128		// Auto 为 true 表示该收款由 bill remit-auto 自动分配登记：首次分配由工具
129		// 按最早欠款账期确定，判重只看客户、总额与备注；false（含旧存档缺字段）
130		// 表示 bill pay / bill remit 的显式分配登记，仍按月份-金额对应关系判重。
131		// 自动与显式分配登记之间不得复用同一收款标识。
132		Auto         bool   `json:"auto,omitempty"`
133		Seq          int64  `json:"seq"` // 全局递增操作序号，决定历史展示顺序
134		CreatedAt    string `json:"created_at"`
135		Revoked      bool   `json:"revoked"`
136		RevokeReason string `json:"revoke_reason,omitempty"`
137		RevokeSeq    int64  `json:"revoke_seq,omitempty"`
138		RevokedAt    string `json:"revoked_at,omitempty"`
139	}
140	
141	// UnmarshalJSON 兼容旧版单账单收款格式（month + amount_fen，无 allocations）：
142	// 读入时归一化为一项分配，之后一律按新格式写回。
143	func (p *payment) UnmarshalJSON(data []byte) error {
144		type plain payment // 去掉方法，避免递归
145		var raw struct {
146			plain
147			Month  string `json:"month"`      // 旧格式：所属账单月份
148			Amount int64  `json:"amount_fen"` // 旧格式：收款金额
149		}
150		if err := json.Unmarshal(data, &raw); err != nil {
151			return err
152		}
153		*p = payment(raw.plain)
154		if len(p.Allocations) == 0 && raw.Month != "" {
155			p.Allocations = []paymentAllocation{{Month: raw.Month, Amount: raw.Amount}}
156			p.Total = raw.Amount
157		}
158		return nil
159	}
160	
161	// amountFor 返回该收款在指定月份的分配金额；无分配时为 0。
162	func (p *payment) amountFor(month string) int64 {
163		for _, al := range p.Allocations {
164			if al.Month == month {
165				return al.Amount
166			}
167		}
168		return 0
169	}
170	
171	// correction 是对一笔未撤销收款的分配更正：客户、总额、备注、原账单及
172	// 应付不变，仅把该笔收款当前生效的分配整体替换为完整新分配。记录一旦写入
173	// 永不删除；首次登记内容永久保留，bill pay / bill remit 仍按原始分配判重，
174	// 更正不影响收款身份。可连续更正，每次以当时最新分配为起点。
175	type correction struct {
176		ID          string              `json:"id"`
177		PaymentID   string              `json:"payment_id"` // 目标收款标识
178		Reason      string              `json:"reason"`
179		Allocations []paymentAllocation `json:"allocations"` // 完整新分配，至少一项，月份不重复，按月份升序保存
180		Seq         int64               `json:"seq"`         // 全局递增操作序号，与调整/收款及其撤销共用
181		CreatedAt   string              `json:"created_at"`
182	}
183	
184	// refund 是对一笔已登记收款的部分退款登记：从该收款当前最新分配涉及的
185	// 月份中实际退回资金，各月退款金额为正整数分，累计不得超过该笔在该月的
186	// 分配。记录一旦写入永不删除、不可撤销；首次退款后该收款的最新分配固定，
187	// 不得再新增分配更正或整笔撤销。退款标识与收款、调整、更正标识命名空间
188	// 相互独立，可同名。
189	type refund struct {
190		ID          string              `json:"id"`
191		PaymentID   string              `json:"payment_id"` // 目标收款标识
192		Reason      string              `json:"reason"`
193		Allocations []paymentAllocation `json:"allocations"` // 各月退款金额，至少一项，月份不重复，按月份升序保存
194		Seq         int64               `json:"seq"`         // 全局递增操作序号，与调整/收款/更正及其撤销共用
195		CreatedAt   string              `json:"created_at"`
196	}
197	
198	// planChange 是阶梯客户的一次按月生效的方案变更：自生效月（UTC 自然月，
199	// 含）起改用目标方案，直到下一次变更；生效月之前的月份不受影响。记录一旦
200	// 写入永不修改或删除；变更不产生账后流水事件，也不占用全局操作序号。
201	type planChange struct {
202		CustomerID string `json:"customer_id"`
203		Month      string `json:"month"`   // YYYY-MM（UTC），生效月（含）
204		PlanID     string `json:"plan_id"` // 目标阶梯计费方案标识
205		Reason     string `json:"reason"`
206		CreatedAt  string `json:"created_at"`
207	}
208	
209	// suspension 是阶梯客户的一段按月暂停区间：自起月（UTC 自然月，含）起
210	// 暂停服务，直到结束月（不含），即 [StartMonth, EndMonth) 覆盖的自然月。
211	// 暂停月不接收用量、不产生月费账单；区间可相接（相接视为连续暂停）但不得
212	// 重叠。记录一旦写入永不修改或删除；暂停不产生账后流水事件，也不占用全局
213	// 操作序号。固定单价客户不适用暂停。
214	type suspension struct {
215		CustomerID string `json:"customer_id"`
216		StartMonth string `json:"start_month"` // YYYY-MM（UTC），暂停起月（含）
217		EndMonth   string `json:"end_month"`   // YYYY-MM（UTC），结束月（不含），严格晚于起月
218		Reason     string `json:"reason"`
219		CreatedAt  string `json:"created_at"`
220	}
221	
222	// withdrawal 是一条用量记录的撤回标记：原记录（客户、时间、数量、标识）永久
223	// 保留在 Usage 中，撤回只追加状态与原因，用于纠正误导入的记录。撤回不可恢复、
224	// 标识不可复用；已撤回用量不参与结算、方案变更预检与暂停区间冲突检查，但相同
225	// 内容的重放仍按原记录判重跳过。撤回只作用于该条记录，不占用全局操作序号。
226	type withdrawal struct {
227		UsageID   string `json:"usage_id"` // 撤回的用量标识（与键一致）
228		Reason    string `json:"reason"`   // 撤回原因，非空
229		CreatedAt string `json:"created_at"`
230	}
231	
232	type state struct {
233		Version     int                     `json:"version"`
234		Customers   map[string]*customer    `json:"customers"`
235		Plans       map[string]*plan        `json:"plans"`                 // 全局唯一方案标识 -> 阶梯计费方案
236		Usage       map[string]*usageRecord `json:"usage"`                 // 全局唯一用量标识 -> 记录
237		Bills       map[string]*bill        `json:"bills"`                 // 客户 + "|" + 月份 -> 账单
238		Adjustments map[string]*adjustment  `json:"adjustments"`           // 全局唯一调整标识 -> 记录
239		Payments    map[string]*payment     `json:"payments"`              // 全局唯一收款标识 -> 记录（与调整标识相互独立，可同名）
240		Corrections map[string]*correction  `json:"corrections"`           // 全局唯一更正标识 -> 记录（与收款、调整标识相互独立，可同名）
241		Refunds     map[string]*refund      `json:"refunds,omitempty"`     // 全局唯一退款标识 -> 记录（与收款、调整、更正标识相互独立，可同名；不可撤销）
242		PlanChanges map[string]*planChange  `json:"plan_changes"`          // 客户 + "|" + 生效月 -> 方案变更（按生效月递增追加，不可改写）
243		Suspensions map[string]*suspension  `json:"suspensions,omitempty"` // 客户 + "|" + 起月 -> 暂停区间（不可改写）
244		Withdrawals map[string]*withdrawal  `json:"withdrawals,omitempty"` // 用量标识 -> 撤回标记（不可恢复，标识不可复用）
245		NextSeq     int64                   `json:"next_seq"`              // 已分配的最大操作序号（调整/收款/更正/退款及其撤销共用；方案变更、暂停与用量撤回不占用）
246		path        string                  `json:"-"`
247	}
248	
249	// loadStore 读取数据目录；目录不存在时按需创建并视为空库。
250	// 已存在但损坏或不可读取的数据一律报错，绝不当作空库覆盖。
251	func loadStore(dir string) (*state, error) {
252		p := filepath.Join(dir, "state.json")
253		data, err := os.ReadFile(p)
254		if err != nil {
255			if errors.Is(err, os.ErrNotExist) {
256				if mkErr := os.MkdirAll(dir, 0o755); mkErr != nil {
257					return nil, fmt.Errorf("无法创建数据目录 %s: %w", dir, mkErr)
258				}
259				return newState(p), nil
260			}
261			return nil, fmt.Errorf("数据文件不可读取 %s: %w", p, err)
262		}
263	
264		var s state
265		dec := json.NewDecoder(bytes.NewReader(data))
266		if err := dec.Decode(&s); err != nil {
267			return nil, fmt.Errorf("数据文件已损坏（不是有效的 JSON）%s: %w", p, err)
268		}
269		// 拒绝完整 JSON 之后的任何非空白内容（包括单独的 ] 或 }），避免静默
270		// 吞掉异常数据；合法尾随空白仍可读取。
271		if off := dec.InputOffset(); off < int64(len(data)) {
272			if strings.TrimSpace(string(data[off:])) != "" {
273				return nil, fmt.Errorf("数据文件已损坏（JSON 之后存在多余内容）: %s", p)
274			}
275		}
276		if err := s.validate(); err != nil {
277			return nil, fmt.Errorf("数据文件已损坏: %w", err)
278		}
279		// 旧版本数据文件没有 plans/adjustments/payments/corrections/refunds/
280		// plan_changes/suspensions/withdrawals/next_seq 字段：视为零方案、零调整、
281		// 零实收、零更正、零退款、零方案变更、零暂停、零撤回（全部用量有效）。
282		if s.Plans == nil {
283			s.Plans = map[string]*plan{}
284		}
285		if s.Adjustments == nil {
286			s.Adjustments = map[string]*adjustment{}
287		}
288		if s.Payments == nil {
289			s.Payments = map[string]*payment{}
290		}
291		if s.Corrections == nil {
292			s.Corrections = map[string]*correction{}
293		}
294		if s.Refunds == nil {
295			s.Refunds = map[string]*refund{}
296		}
297		if s.PlanChanges == nil {
298			s.PlanChanges = map[string]*planChange{}
299		}
300		if s.Suspensions == nil {
301			s.Suspensions = map[string]*suspension{}
302		}
303		if s.Withdrawals == nil {
304			s.Withdrawals = map[string]*withdrawal{}
305		}
306		s.path = p
307		return &s, nil
308	}
309	
310	func newState(p string) *state {
311		return &state{
312			Version:     stateVersion,
313			Customers:   map[string]*customer{},
314			Plans:       map[string]*plan{},
315			Usage:       map[string]*usageRecord{},
316			Bills:       map[string]*bill{},
317			Adjustments: map[string]*adjustment{},
318			Payments:    map[string]*payment{},
319			Corrections: map[string]*correction{},
320			Refunds:     map[string]*refund{},
321			PlanChanges: map[string]*planChange{},
322			Suspensions: map[string]*suspension{},
323			Withdrawals: map[string]*withdrawal{},
324			path:        p,
325		}
326	}
327	
328	// validate 对读入的库做一致性检查，任何异常都按损坏处理。
329	func (s *state) validate() error {
330		if s.Version != stateVersion {
331			return fmt.Errorf("不支持的数据版本 %d（仅支持 %d）", s.Version, stateVersion)
332		}
333		if s.Customers == nil || s.Usage == nil || s.Bills == nil {
334			return errors.New("缺少必要的数据节")
335		}
336		for id, p := range s.Plans {
337			if p == nil {
338				return fmt.Errorf("方案 %q 的数据为空", id)
339			}
340			if p.ID != id {
341				return fmt.Errorf("方案标识不一致: 键 %q / 记录 %q", id, p.ID)
342			}
343			if err := validatePlanRules(p); err != nil {
344				return err
345			}
346		}
347		for id, c := range s.Customers {
348			if c == nil {
349				return fmt.Errorf("客户 %q 的数据为空", id)
350			}
351			if c.ID != id {
352				return fmt.Errorf("客户标识不一致: 键 %q / 记录 %q", id, c.ID)
353			}
354			if c.ID == "" || c.Name == "" {
355				return fmt.Errorf("客户 %q 的标识或名称为空", id)
356			}
357			if c.Price < 0 {
358				return fmt.Errorf("客户 %q 单价为负", id)
359			}
360			if c.PlanID != "" {
361				if _, ok := s.Plans[c.PlanID]; !ok {
362					return fmt.Errorf("客户 %q 绑定了不存在的方案 %q", id, c.PlanID)
363				}
364			}
365		}
366		// 方案变更：键、客户（须为绑定阶梯方案的客户）、目标方案、生效月与
367		// 原因都必须自洽；同一客户的变更生效月由键保证唯一。
368		for key, ch := range s.PlanChanges {
369			if ch == nil {
370				return fmt.Errorf("方案变更 %q 的数据为空", key)
371			}
372			if planChangeKey(ch.CustomerID, ch.Month) != key {
373				return fmt.Errorf("方案变更键不一致: 键 %q / 客户月份 %s|%s", key, ch.CustomerID, ch.Month)
374			}
375			c, ok := s.Customers[ch.CustomerID]
376			if !ok {
377				return fmt.Errorf("方案变更 %q 引用了不存在的客户 %q", key, ch.CustomerID)
378			}
379			if c.PlanID == "" {
380				return fmt.Errorf("方案变更 %q 的客户 %q 未绑定阶梯方案", key, ch.CustomerID)
381			}
382			if !validMonth(ch.Month) {
383				return fmt.Errorf("方案变更 %q 的生效月无效", key)
384			}
385			if _, ok := s.Plans[ch.PlanID]; !ok {
386				return fmt.Errorf("方案变更 %q 引用了不存在的方案 %q", key, ch.PlanID)
387			}
388			if strings.TrimSpace(ch.Reason) == "" {
389				return fmt.Errorf("方案变更 %q 的原因为空", key)
390			}
391		}
392		for id, u := range s.Usage {
393			if u == nil {
394				return fmt.Errorf("用量 %q 的数据为空", id)
395			}
396			if u.ID != id {
397				return fmt.Errorf("用量标识不一致: 键 %q / 记录 %q", id, u.ID)
398			}
399			if u.ID == "" {
400				return errors.New("存在空的用量标识")
401			}
402			if _, ok := s.Customers[u.CustomerID]; !ok {
403				return fmt.Errorf("用量 %q 引用了不存在的客户 %q", u.ID, u.CustomerID)
404			}
405			if u.Quantity <= 0 {
406				return fmt.Errorf("用量 %q 的数量非正", u.ID)
407			}
408			if _, err := time.Parse(time.RFC3339, u.Time); err != nil {
409				return fmt.Errorf("用量 %q 的时间不是 RFC3339: %w", u.ID, err)
410			}
411		}
412		// 撤回标记：键与记录一致、目标用量存在（撤回目标失效即损坏）、原因非空。
413		// 原用量记录仍按上面的规则完整校验（格式、正数量、客户存在性），撤回不
414		// 删除或改写原记录。旧文件缺少撤回记录视为全部用量有效（Withdrawals 已
415		// 在载入时补为空表）。
416		for id, w := range s.Withdrawals {
417			if w == nil {
418				return fmt.Errorf("用量 %q 的撤回记录为空", id)
419			}
420			if w.UsageID != id {
421				return fmt.Errorf("撤回记录键不一致: 键 %q / 用量标识 %q", id, w.UsageID)
422			}
423			if w.UsageID == "" {
424				return errors.New("存在空用量标识的撤回记录")
425			}
426			if _, ok := s.Usage[w.UsageID]; !ok {
427				return fmt.Errorf("撤回记录引用了不存在的用量 %q（撤回目标失效）", w.UsageID)
428			}
429			if strings.TrimSpace(w.Reason) == "" {
430				return fmt.Errorf("用量 %q 的撤回原因为空", w.UsageID)
431			}
432		}
433		for key, b := range s.Bills {
434			if b == nil {
435				return fmt.Errorf("账单 %q 的数据为空", key)
436			}
437			if billKey(b.CustomerID, b.Month) != key {
438				return fmt.Errorf("账单键不一致: 键 %q / 客户月份 %s|%s", key, b.CustomerID, b.Month)
439			}
440			if _, ok := s.Customers[b.CustomerID]; !ok {
441				return fmt.Errorf("账单 %q 引用了不存在的客户 %q", key, b.CustomerID)
442			}
443			if !validMonth(b.Month) {
444				return fmt.Errorf("账单 %q 的月份无效", key)
445			}
446			if b.MonthlyFee < 0 {
447				return fmt.Errorf("账单 %q 的月费为负", key)
448			}
449			// 仅月费大于 0 的账单允许空用量明细（无用量也须出账收取月费）。
450			if len(b.Lines) == 0 && b.MonthlyFee == 0 {
451				return fmt.Errorf("账单 %q 没有明细", key)
452			}
453			var qty, fee int64
454			for _, ln := range b.Lines {
455				u, ok := s.Usage[ln.UsageID]
456				if !ok {
457					return fmt.Errorf("账单 %q 引用了不存在的用量 %q", key, ln.UsageID)
458				}
459				// 已撤回用量不参与结算，账单不得把已撤回记录视为待计费用量。
460				if _, withdrawn := s.Withdrawals[ln.UsageID]; withdrawn {
461					return fmt.Errorf("账单 %q 引用了已撤回的用量 %q", key, ln.UsageID)
462				}
463				if u.CustomerID != b.CustomerID || u.Time != ln.Time || u.Quantity != ln.Quantity {
464					return fmt.Errorf("账单 %q 的明细 %q 与用量记录不一致", key, ln.UsageID)
465				}
466				if !inMonth(u.Time, b.Month) {
467					return fmt.Errorf("账单 %q 的明细 %q 不在账期内", key, ln.UsageID)
468				}
469				var err error
470				qty, err = add64(qty, ln.Quantity)
471				if err != nil {
472					return fmt.Errorf("账单 %q 汇总数量溢出", key)
473				}
474				fee, err = add64(fee, ln.LineFee)
475				if err != nil {
476					return fmt.Errorf("账单 %q 汇总金额溢出", key)
477				}
478			}
479			if qty != b.TotalQty {
480				return fmt.Errorf("账单 %q 总数量与明细不符", key)
481			}
482			// 原总金额 = 月费 + 全月用量费；月费不计入逐条用量小计，故明细
483			// 小计之和等于用量费（总金额 − 月费）。月费与总金额均非负，相减
484			// 不会溢出；总金额为负或小于月费时此处必然不符。
485			if usageFee := b.TotalFee - b.MonthlyFee; fee != usageFee {
486				return fmt.Errorf("账单 %q 总金额不等于月费加全月用量费（明细小计合计 %d 分，月费 %d 分，总金额 %d 分）",
487					key, fee, b.MonthlyFee, b.TotalFee)
488			}
489			c := s.Customers[b.CustomerID]
490			switch b.Pricing {
491			case "", "fixed":
492				// 固定单价账单：每条小计必须等于 数量×客户固定单价，且不得
493				// 携带阶梯方案信息、分段或月费。
494				if b.PlanID != "" || b.PlanName != "" || len(b.PlanTiers) > 0 || len(b.TierTotals) > 0 {
495					return fmt.Errorf("账单 %q 是固定单价账单但携带阶梯方案信息", key)
496				}
497				if b.MonthlyFee != 0 {
498					return fmt.Errorf("账单 %q 是固定单价账单但携带月费", key)
499				}
500				for _, ln := range b.Lines {
501					if len(ln.Segments) > 0 {
502						return fmt.Errorf("账单 %q 的明细 %q 携带阶梯分段", key, ln.UsageID)
503					}
504					lf, err := mul64(ln.Quantity, c.Price)
505					if err != nil {
506						return fmt.Errorf("账单 %q 明细 %q 小计溢出", key, ln.UsageID)
507					}
508					if lf != ln.LineFee {
509						return fmt.Errorf("账单 %q 明细 %q 小计与数量×单价不符", key, ln.UsageID)
510					}
511				}
512				if b.UnitPrice != c.Price {
513					return fmt.Errorf("账单 %q 单价与客户固定单价不符", key)
514				}
515			case "tiered":
516				if err := s.validateTieredBill(key, b, c); err != nil {
517					return err
518				}
519			default:
520				return fmt.Errorf("账单 %q 的计价类型 %q 未知", key, b.Pricing)
521			}
522			// 封账期内不得存在游离于账单之外的有效用量（封账后新增被禁止，
523			// 而已入账记录理应全部在明细中）；已撤回用量不计费用，允许存在
524			// 于已封账月份而不进入账单。
525			for _, u := range s.Usage {
526				if _, withdrawn := s.Withdrawals[u.ID]; withdrawn {
527					continue
528				}
529				if u.CustomerID == b.CustomerID && inMonth(u.Time, b.Month) {
530					found := false
531					for _, ln := range b.Lines {
532						if ln.UsageID == u.ID {
533							found = true
534							break
535						}
536					}
537					if !found {
538						return fmt.Errorf("客户 %s 的 %s 已封账，但用量 %q 未计入账单", b.CustomerID, b.Month, u.ID)
539					}
540				}
541			}
542		}
543	
544		// 暂停区间：键、客户（须为绑定阶梯方案的客户）、区间与原因都必须自洽；
545		// 同一客户的区间不得重叠（可以相接）；暂停月内不得存在有效（未撤回）
546		// 用量或账单。
547		// 旧文件缺少暂停记录视为正常服务（Suspensions 已在载入时补为空表）。
548		for key, su := range s.Suspensions {
549			if su == nil {
550				return fmt.Errorf("暂停区间 %q 的数据为空", key)
551			}
552			if suspensionKey(su.CustomerID, su.StartMonth) != key {
553				return fmt.Errorf("暂停区间键不一致: 键 %q / 客户起月 %s|%s", key, su.CustomerID, su.StartMonth)
554			}
555			c, ok := s.Customers[su.CustomerID]
556			if !ok {
557				return fmt.Errorf("暂停区间 %q 引用了不存在的客户 %q", key, su.CustomerID)
558			}
559			if c.PlanID == "" {
560				return fmt.Errorf("暂停区间 %q 的客户 %q 未绑定阶梯方案（固定单价客户不适用暂停）", key, su.CustomerID)
561			}
562			if !validMonth(su.StartMonth) {
563				return fmt.Errorf("暂停区间 %q 的起月无效", key)
564			}
565			if !validMonth(su.EndMonth) || su.EndMonth <= su.StartMonth {
566				return fmt.Errorf("暂停区间 %q 的结束月无效（结束月必须是晚于起月 %s 的 YYYY-MM）", key, su.StartMonth)
567			}
568			if strings.TrimSpace(su.Reason) == "" {
569				return fmt.Errorf("暂停区间 %q 的原因为空", key)
570			}
571		}
572		for customerID := range s.Customers {
573			list := s.suspensionsFor(customerID)
574			for i := 1; i < len(list); i++ {
575				if list[i].StartMonth < list[i-1].EndMonth {
576					return fmt.Errorf("客户 %s 的暂停区间 %s..%s 与 %s..%s 重叠（区间可以相接但不得重叠）",
577						customerID, list[i-1].StartMonth, list[i-1].EndMonth, list[i].StartMonth, list[i].EndMonth)
578				}
579			}
580			for _, su := range list {
581				for _, u := range s.Usage {
582					// 已撤回用量不参与用量冲突判断，可存在于随后暂停的月份。
583					if _, withdrawn := s.Withdrawals[u.ID]; withdrawn {
584						continue
585					}
586					if u.CustomerID == customerID && monthInRange(utcMonth(u.Time), su.StartMonth, su.EndMonth) {
587						return fmt.Errorf("客户 %s 在暂停区间 %s..%s（不含结束月）内存在用量 %q（%s）",
588							customerID, su.StartMonth, su.EndMonth, u.ID, utcMonth(u.Time))
589					}
590				}
591				for _, b := range s.Bills {
592					if b.CustomerID == customerID && monthInRange(b.Month, su.StartMonth, su.EndMonth) {
593						return fmt.Errorf("客户 %s 在暂停区间 %s..%s（不含结束月）内存在账单（月份 %s），暂停月不得封账",
594							customerID, su.StartMonth, su.EndMonth, b.Month)
595					}
596				}
597			}
598		}
599	
600		// 调整与收款记录：标识、内容、引用与序号都必须自洽。
601		// 调整与收款共用同一个全局操作序号池；两者标识命名空间相互独立，
602		// 允许同名，各自判重与撤销。
603		if s.NextSeq < 0 {
604			return fmt.Errorf("操作序号计数器为负: %d", s.NextSeq)
605		}
606		seenSeq := make(map[int64]string) // 全局操作序号（登记与撤销共用同一池）-> 来源描述
607		for id, a := range s.Adjustments {
608			if a == nil {
609				return fmt.Errorf("调整 %q 的数据为空", id)
610			}
611			if a.ID != id {
612				return fmt.Errorf("调整标识不一致: 键 %q / 记录 %q", id, a.ID)
613			}
614			if a.ID == "" {
615				return errors.New("存在空的调整标识")
616			}
617			if a.Amount == 0 {
618				return fmt.Errorf("调整 %q 的金额为零", id)
619			}
620			if strings.TrimSpace(a.Reason) == "" {
621				return fmt.Errorf("调整 %q 的原因为空", id)
622			}
623			if !validMonth(a.Month) {
624				return fmt.Errorf("调整 %q 的月份无效", id)
625			}
626			if _, ok := s.Customers[a.CustomerID]; !ok {
627				return fmt.Errorf("调整 %q 引用了不存在的客户 %q", id, a.CustomerID)
628			}
629			if _, ok := s.Bills[billKey(a.CustomerID, a.Month)]; !ok {
630				return fmt.Errorf("调整 %q 引用了不存在的账单（客户 %s 月份 %s）", id, a.CustomerID, a.Month)
631			}
632			if a.Seq < 1 || a.Seq > s.NextSeq {
633				return fmt.Errorf("调整 %q 的操作序号越界", id)
634			}
635			if prev, dup := seenSeq[a.Seq]; dup {
636				return fmt.Errorf("调整 %q 与 %q 的操作序号重复", id, prev)
637			}
638			seenSeq[a.Seq] = "调整 " + id
639			if a.Revoked {
640				if strings.TrimSpace(a.RevokeReason) == "" {
641					return fmt.Errorf("调整 %q 已撤销但撤销原因为空", id)
642				}
643				if a.RevokeSeq <= a.Seq || a.RevokeSeq > s.NextSeq {
644					return fmt.Errorf("调整 %q 的撤销序号越界", id)
645				}
646				if prev, dup := seenSeq[a.RevokeSeq]; dup {
647					return fmt.Errorf("撤销调整 %q 与 %q 的操作序号重复", id, prev)
648				}
649				seenSeq[a.RevokeSeq] = "撤销调整 " + id
650			} else if a.RevokeReason != "" || a.RevokeSeq != 0 {
651				return fmt.Errorf("调整 %q 未撤销但存在撤销信息", id)
652			}
653		}
654		for id, p := range s.Payments {
655			if p == nil {
656				return fmt.Errorf("收款 %q 的数据为空", id)
657			}
658			if p.ID != id {
659				return fmt.Errorf("收款标识不一致: 键 %q / 记录 %q", id, p.ID)
660			}
661			if p.ID == "" {
662				return errors.New("存在空的收款标识")
663			}
664			if p.Total <= 0 {
665				return fmt.Errorf("收款 %q 的总额不是正整数", id)
666			}
667			if strings.TrimSpace(p.Note) == "" {
668				return fmt.Errorf("收款 %q 的备注为空", id)
669			}
670			if _, ok := s.Customers[p.CustomerID]; !ok {
671				return fmt.Errorf("收款 %q 引用了不存在的客户 %q", id, p.CustomerID)
672			}
673			if len(p.Allocations) == 0 {
674				return fmt.Errorf("收款 %q 没有分配", id)
675			}
676			seenMonths := make(map[string]bool)
677			var sum int64
678			for _, al := range p.Allocations {
679				if !validMonth(al.Month) {
680					return fmt.Errorf("收款 %q 的分配月份 %q 无效", id, al.Month)
681				}
682				if seenMonths[al.Month] {
683					return fmt.Errorf("收款 %q 的分配月份 %s 重复", id, al.Month)
684				}
685				seenMonths[al.Month] = true
686				if al.Amount <= 0 {
687					return fmt.Errorf("收款 %q 在 %s 的分配金额不是正整数", id, al.Month)
688				}
689				if _, ok := s.Bills[billKey(p.CustomerID, al.Month)]; !ok {
690					return fmt.Errorf("收款 %q 的分配引用了不存在的账单（客户 %s 月份 %s）", id, p.CustomerID, al.Month)
691				}
692				var err error
693				sum, err = add64(sum, al.Amount)
694				if err != nil {
695					return fmt.Errorf("收款 %q 的分配金额汇总溢出: %w", id, err)
696				}
697			}
698			if sum != p.Total {
699				return fmt.Errorf("收款 %q 的分配合计 %d 分与总额 %d 分不一致", id, sum, p.Total)
700			}
701			if p.Seq < 1 || p.Seq > s.NextSeq {
702				return fmt.Errorf("收款 %q 的操作序号越界", id)
703			}
704			if prev, dup := seenSeq[p.Seq]; dup {
705				return fmt.Errorf("收款 %q 与 %q 的操作序号重复", id, prev)
706			}
707			seenSeq[p.Seq] = "收款 " + id
708			if p.Revoked {
709				if strings.TrimSpace(p.RevokeReason) == "" {
710					return fmt.Errorf("收款 %q 已撤销但撤销原因为空", id)
711				}
712				if p.RevokeSeq <= p.Seq || p.RevokeSeq > s.NextSeq {
713					return fmt.Errorf("收款 %q 的撤销序号越界", id)
714				}
715				if prev, dup := seenSeq[p.RevokeSeq]; dup {
716					return fmt.Errorf("撤销收款 %q 与 %q 的操作序号重复", id, prev)
717				}
718				seenSeq[p.RevokeSeq] = "撤销收款 " + id
719			} else if p.RevokeReason != "" || p.RevokeSeq != 0 {
720				return fmt.Errorf("收款 %q 未撤销但存在撤销信息", id)
721			}
722		}
723		// 分配更正记录：标识、目标收款、原因、新分配与序号都必须自洽。
724		// 更正标识与收款、调整标识命名空间相互独立，允许同名。
725		for id, c := range s.Corrections {
726			if c == nil {
727				return fmt.Errorf("更正 %q 的数据为空", id)
728			}
729			if c.ID != id {
730				return fmt.Errorf("更正标识不一致: 键 %q / 记录 %q", id, c.ID)
731			}
732			if c.ID == "" {
733				return errors.New("存在空的更正标识")
734			}
735			p, ok := s.Payments[c.PaymentID]
736			if !ok {
737				return fmt.Errorf("更正 %q 引用了不存在的收款 %q", id, c.PaymentID)
738			}
739			if strings.TrimSpace(c.Reason) == "" {
740				return fmt.Errorf("更正 %q 的原因为空", id)
741			}
742			if len(c.Allocations) == 0 {
743				return fmt.Errorf("更正 %q 没有新分配", id)
744			}
745			seenMonths := make(map[string]bool)
746			var sum int64
747			for _, al := range c.Allocations {
748				if !validMonth(al.Month) {
749					return fmt.Errorf("更正 %q 的分配月份 %q 无效", id, al.Month)
750				}
751				if seenMonths[al.Month] {
752					return fmt.Errorf("更正 %q 的分配月份 %s 重复", id, al.Month)
753				}
754				seenMonths[al.Month] = true
755				if al.Amount <= 0 {
756					return fmt.Errorf("更正 %q 在 %s 的分配金额不是正整数", id, al.Month)
757				}
758				if _, ok := s.Bills[billKey(p.CustomerID, al.Month)]; !ok {
759					return fmt.Errorf("更正 %q 的分配引用了不存在的账单（客户 %s 月份 %s）", id, p.CustomerID, al.Month)
760				}
761				var err error
762				sum, err = add64(sum, al.Amount)
763				if err != nil {
764					return fmt.Errorf("更正 %q 的分配金额汇总溢出: %w", id, err)
765				}
766			}
767			if sum != p.Total {
768				return fmt.Errorf("更正 %q 的分配合计 %d 分与关联收款 %q 的总额 %d 分不一致", id, sum, c.PaymentID, p.Total)
769			}
770			if c.Seq <= p.Seq || c.Seq > s.NextSeq {
771				return fmt.Errorf("更正 %q 的操作序号越界", id)
772			}
773			if p.Revoked && c.Seq > p.RevokeSeq {
774				return fmt.Errorf("更正 %q 的操作序号晚于关联收款 %q 的撤销序号", id, c.PaymentID)
775			}
776			if prev, dup := seenSeq[c.Seq]; dup {
777				return fmt.Errorf("更正 %q 与 %q 的操作序号重复", id, prev)
778			}
779			seenSeq[c.Seq] = "更正 " + id
780		}
781		// 退款记录：标识、目标收款、原因、各月退款与序号都必须自洽。退款标识与
782		// 收款、调整、更正标识命名空间相互独立，允许同名。退款只作用于未撤销
783		// 收款的最新分配涉及的月份；首次退款后该收款不得再更正或整笔撤销，
784		// 因此全部退款都以当前最新分配为准核验，累计不得超退。旧文件缺少退款
785		// 记录视为无退款（Refunds 已在载入时补为空表）。
786		for id, r := range s.Refunds {
787			if r == nil {
788				return fmt.Errorf("退款 %q 的数据为空", id)
789			}
790			if r.ID != id {
791				return fmt.Errorf("退款标识不一致: 键 %q / 记录 %q", id, r.ID)
792			}
793			if r.ID == "" {
794				return errors.New("存在空的退款标识")
795			}
796			p, ok := s.Payments[r.PaymentID]
797			if !ok {
798				return fmt.Errorf("退款 %q 引用了不存在的收款 %q（退款目标失效）", id, r.PaymentID)
799			}
800			if strings.TrimSpace(r.Reason) == "" {
801				return fmt.Errorf("退款 %q 的原因为空", id)
802			}
803			if len(r.Allocations) == 0 {
804				return fmt.Errorf("退款 %q 没有月份金额清单", id)
805			}
806			current := currentAllocations(s, p)
807			seenMonths := make(map[string]bool)
808			for _, al := range r.Allocations {
809				if !validMonth(al.Month) {
810					return fmt.Errorf("退款 %q 的月份 %q 无效", id, al.Month)
811				}
812				if seenMonths[al.Month] {
813					return fmt.Errorf("退款 %q 的月份 %s 重复", id, al.Month)
814				}
815				seenMonths[al.Month] = true
816				if al.Amount <= 0 {
817					return fmt.Errorf("退款 %q 在 %s 的金额不是正整数", id, al.Month)
818				}
819				if allocAmountFor(current, al.Month) <= 0 {
820					return fmt.Errorf("退款 %q 的月份 %s 不在收款 %q 的最新分配中（仅允许退最新分配涉及的月份）", id, al.Month, r.PaymentID)
821				}
822			}
823			if r.Seq <= p.Seq || r.Seq > s.NextSeq {
824				return fmt.Errorf("退款 %q 的操作序号越界", id)
825			}
826			if prev, dup := seenSeq[r.Seq]; dup {
827				return fmt.Errorf("退款 %q 与 %q 的操作序号重复", id, prev)
828			}
829			seenSeq[r.Seq] = "退款 " + id
830		}
831		// 逐收款核验退款相关约束：已退款的收款不得被整笔撤销；首次退款后不得
832		// 再出现更正（最新分配已固定）；各月累计退款不得超过该笔在该月的最新
833		// 分配（累计超退即余额异常）。
834		for pid, p := range s.Payments {
835			refs := refundsFor(s, pid)
836			if len(refs) == 0 {
837				continue
838			}
839			firstRefundSeq := refs[0].Seq // refundsFor 按序号升序
840			if p.Revoked {
841				return fmt.Errorf("收款 %q 已发生退款（首次退款序号 %d）却又被整笔撤销（序号 %d），操作先后非法", pid, firstRefundSeq, p.RevokeSeq)
842			}
843			for _, c := range s.Corrections {
844				if c.PaymentID == pid && c.Seq > firstRefundSeq {
845					return fmt.Errorf("更正 %q 的序号 %d 晚于收款 %q 的首次退款序号 %d（首次退款后最新分配已固定），操作先后非法", c.ID, c.Seq, pid, firstRefundSeq)
846				}
847			}
848			current := currentAllocations(s, p)
849			totals := make(map[string]int64)
850			for _, r := range refs {
851				for _, al := range r.Allocations {
852					sum, err := add64(totals[al.Month], al.Amount)
853					if err != nil {
854						return fmt.Errorf("收款 %q 在 %s 的累计退款溢出有符号 64 位整数范围，余额异常", pid, al.Month)
855					}
856					totals[al.Month] = sum
857				}
858			}
859			for month, refunded := range totals {
860				if alloc := allocAmountFor(current, month); refunded > alloc {
861					return fmt.Errorf("收款 %q 在 %s 的累计退款 %d 分超过该月分配 %d 分（累计超退），余额异常", pid, month, refunded, alloc)
862				}
863			}
864		}
865		// 每张账单：当前应付（原总金额 + 全部未撤销调整净额）必须介于
866		// 0 与有符号 64 位最大值之间；实收（全部未撤销收款按最新分配在该月
867		// 计入并扣除退款后的合计）必须满足 0 ≤ 实收 ≤ 当前应付。越界说明
868		// 金额与记录不一致。
869		for key, b := range s.Bills {
870			_, payable, err := billTotals(b, adjustmentsFor(s, b.CustomerID, b.Month))
871			if err != nil {
872				return fmt.Errorf("账单 %q 的调整金额与记录不一致: %w", key, err)
873			}
874			received, err := paymentReceived(s, b.CustomerID, b.Month)
875			if err != nil {
876				return fmt.Errorf("账单 %q 的收款金额与记录不一致: %w", key, err)
877			}
878			if received > payable {
879				return fmt.Errorf("账单 %q 的实收 %d 分超过当前应付 %d 分", key, received, payable)
880			}
881		}
882		return nil
883	}
