885	// validatePlanRules 校验阶梯方案的标识、名称、月费与阶梯规则本身自洽：
886	// 月费为非负整数分，至少一档，有限上限为严格递增的正整数，最后一档无
887	// 上限，单价非负。
888	func validatePlanRules(p *plan) error {
889		if p.ID == "" || p.Name == "" {
890			return fmt.Errorf("方案 %q 的标识或名称为空", p.ID)
891		}
892		if p.MonthlyFee < 0 {
893			return fmt.Errorf("方案 %q 的月费为负", p.ID)
894		}
895		if len(p.Tiers) == 0 {
896			return fmt.Errorf("方案 %q 至少需要一档阶梯", p.ID)
897		}
898		prev := int64(0)
899		for i, t := range p.Tiers {
900			if t.Price < 0 {
901				return fmt.Errorf("方案 %q 第 %d 档单价为负", p.ID, i+1)
902			}
903			if i == len(p.Tiers)-1 {
904				if t.Limit != 0 {
905					return fmt.Errorf("方案 %q 最后一档必须无上限", p.ID)
906				}
907			} else {
908				if t.Limit <= 0 {
909					return fmt.Errorf("方案 %q 第 %d 档上限必须是正整数", p.ID, i+1)
910				}
911				if t.Limit <= prev {
912					return fmt.Errorf("方案 %q 的有限上限必须严格递增", p.ID)
913				}
914				prev = t.Limit
915			}
916		}
917		return nil
918	}
