946	// sortedByInstant 判定用量记录是否按（解析后的时间点升序、同一时间按
947	// 标识字典序）排列，即阶梯计价的计价顺序。
948	func sortedByInstant(recs []*usageRecord) bool {
949		for i := 1; i < len(recs); i++ {
950			ti, _ := time.Parse(time.RFC3339, recs[i-1].Time)
951			tj, _ := time.Parse(time.RFC3339, recs[i].Time)
952			ui, uj := ti.UTC(), tj.UTC()
953			if uj.Before(ui) || (uj.Equal(ui) && recs[i].ID <= recs[i-1].ID) {
954				return false
955			}
956		}
957		return true
958	}
