960	// validateTieredBill 校验阶梯账单：方案引用有效、快照与方案一致、账单方案
961	// 符合账期月的方案安排，并按保存的方案规则从零累计重放计价，逐条比对分段、
962	// 小计、各档合计与总金额；任何不符都视为数据损坏。
963	func (s *state) validateTieredBill(key string, b *bill, c *customer) error {
964		if b.PlanID == "" {
965			return fmt.Errorf("账单 %q 缺少方案标识", key)
966		}
967		p, ok := s.Plans[b.PlanID]
968		if !ok {
969			return fmt.Errorf("账单 %q 引用了不存在的方案 %q", key, b.PlanID)
970		}
971		if b.PlanName != p.Name {
972			return fmt.Errorf("账单 %q 的方案名称快照与方案 %q 不符", key, b.PlanID)
973		}
974		if !tiersEqual(b.PlanTiers, p.Tiers) {
975			return fmt.Errorf("账单 %q 的方案规则快照与方案 %q 不符", key, b.PlanID)
976		}
977		if b.MonthlyFee != p.MonthlyFee {
978			return fmt.Errorf("账单 %q 的月费快照与方案 %q 不符", key, b.PlanID)
979		}
980		// 账单方案必须符合账期安排：创建时绑定的初始方案被生效月不晚于
981		// 账期月的最后一次变更替换（无变更时即初始绑定，兼容旧存档）。
982		if want := s.effectivePlanID(c, b.Month); want != b.PlanID {
983			return fmt.Errorf("账单 %q 的方案 %q 与账期 %s 安排的方案 %q 不一致", key, b.PlanID, b.Month, want)
984		}
985		if b.UnitPrice != 0 {
986			return fmt.Errorf("账单 %q 是阶梯账单但保存了统一单价", key)
987		}
988		if len(b.TierTotals) != len(p.Tiers) {
989			return fmt.Errorf("账单 %q 的分档合计档数与方案规则不符", key)
990		}
991		// 明细必须按计价顺序排列（前面已逐条核验与用量记录一致）。
992		recs := make([]*usageRecord, len(b.Lines))
993		for i, ln := range b.Lines {
994			recs[i] = s.Usage[ln.UsageID]
995		}
996		if !sortedByInstant(recs) {
997			return fmt.Errorf("账单 %q 的明细未按计价顺序（时间点升序、同一时间按标识字典序）排列", key)
998		}
999		priced, err := tieredPrice(p.Tiers, recs)
1000		if err != nil {
1001			return fmt.Errorf("账单 %q 按方案规则计价失败: %w", key, err)
1002		}
1003		for i, ln := range b.Lines {
1004			if !segmentsEqual(ln.Segments, priced.lines[i].segments) {
1005				return fmt.Errorf("账单 %q 的明细 %q 分段与计价规则不符", key, ln.UsageID)
1006			}
1007			if ln.LineFee != priced.lines[i].fee {
1008				return fmt.Errorf("账单 %q 的明细 %q 小计与计价规则不符", key, ln.UsageID)
1009			}
1010		}
1011		for i, tt := range b.TierTotals {
1012			if tt.Quantity != priced.tierQty[i] || tt.Fee != priced.tierFee[i] {
1013				return fmt.Errorf("账单 %q 的第 %d 档合计与计价规则不符", key, i+1)
1014			}
1015		}
1016		// 原总金额 = 月费 + 全月用量费；月费不进入分档合计与逐条小计。
1017		wantTotal, err := add64(priced.totalFee, b.MonthlyFee)
1018		if err != nil || wantTotal != b.TotalFee {
1019			return fmt.Errorf("账单 %q 总金额不等于月费加全月用量费", key)
1020		}
1021		return nil
1022	}
