1024	// save 整体原子落盘：先写临时文件并同步，再 rename 覆盖。
1025	// 只有完整保存成功后调用方才会向用户报告成功。
1026	func (s *state) save() error {
1027		if err := s.validate(); err != nil {
1028			return fmt.Errorf("拒绝写入不一致的数据: %w", err)
1029		}
1030		data, err := json.MarshalIndent(s, "", "  ")
1031		if err != nil {
1032			return fmt.Errorf("序列化数据失败: %w", err)
1033		}
1034		data = append(data, '\n')
1035	
1036		tmp := s.path + ".tmp"
1037		f, err := os.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0o644)
1038		if err != nil {
1039			return fmt.Errorf("写入临时数据文件失败: %w", err)
1040		}
1041		if _, err := f.Write(data); err != nil {
1042			f.Close()
1043			os.Remove(tmp)
1044			return fmt.Errorf("写入临时数据文件失败: %w", err)
1045		}
1046		if err := f.Sync(); err != nil {
1047			f.Close()
1048			os.Remove(tmp)
1049			return fmt.Errorf("同步数据文件失败: %w", err)
1050		}
1051		if err := f.Close(); err != nil {
1052			os.Remove(tmp)
1053			return fmt.Errorf("关闭数据文件失败: %w", err)
1054		}
1055		if err := os.Rename(tmp, s.path); err != nil {
1056			os.Remove(tmp)
1057			return fmt.Errorf("替换数据文件失败: %w", err)
1058		}
1059		if dir, err := os.Open(filepath.Dir(s.path)); err == nil {
1060			dir.Sync()
1061			dir.Close()
1062		}
1063		return nil
1064	}
