1218	}
1219	
1220	// paymentReceived 返回全部未撤销收款按最新分配在指定月份计入并扣除退款后
1221	// 的实收之和。各笔净额（分配减累计退款）均为非负整数，用非负 64 位加法
1222	// 累加，溢出时返回错误。
1223	func paymentReceived(s *state, customerID, month string) (int64, error) {
1224		var received int64
1225		for _, p := range s.Payments {
1226			if p.CustomerID != customerID || p.Revoked {
1227				continue
1228			}
1229			amt := allocAmountFor(currentAllocations(s, p), month) - refundedForMonth(s, p.ID, month)
1230			if amt <= 0 {
1231				continue
1232			}
1233			var err error
1234			received, err = add64(received, amt)
1235			if err != nil {
1236				return 0, err
1237			}
1238		}
1239		return received, nil
1240	}
1241	
1242	// refundsFor 返回某收款的全部退款，按操作序号升序。
1243	func refundsFor(s *state, paymentID string) []*refund {
1244		var list []*refund
1245		for _, r := range s.Refunds {
1246			if r.PaymentID == paymentID {
1247				list = append(list, r)
1248			}
1249		}
1250		sort.Slice(list, func(i, j int) bool { return list[i].Seq < list[j].Seq })
1251		return list
1252	}
1253	
1254	// refundedForMonth 返回某收款在指定月份的累计退款金额（分）；无退款时为 0。
1255	// 数据在载入时已校验累计不超退，合计不超过该月分配，不会溢出。
1256	func refundedForMonth(s *state, paymentID, month string) int64 {
1257		var total int64
1258		for _, r := range s.Refunds {
1259			if r.PaymentID == paymentID {
1260				total += allocAmountFor(r.Allocations, month)
1261			}
1262		}
1263		return total
1264	}
1265	
1266	// paymentHasRefunds 报告某收款是否已发生退款。首次退款后该收款的最新分配
1267	// 固定，不得再新增分配更正或整笔撤销。
1268	func paymentHasRefunds(s *state, paymentID string) bool {
1269		for _, r := range s.Refunds {
1270			if r.PaymentID == paymentID {
1271				return true
1272			}
1273		}
1274		return false
1275	}
1276	
1277	// errPayableOutOfRange 表示当前应付越出 [0, 有符号 64 位最大值]。
1278	var errPayableOutOfRange = errors.New("当前应付越界（须介于 0 与有符号 64 位最大值之间）")
1279	
1280	// billTotals 计算全部未撤销调整的净额与当前应付（原总金额 + 净额）。
1281	// 净额按 128 位精确求和（与顺序无关），再校验应付落在
1282	// [0, 有符号 64 位最大值] 内，全程整数运算。
1283	func billTotals(b *bill, adjs []*adjustment) (net, payable int64, err error) {
1284		var amounts []int64
1285		for _, a := range adjs {
1286			if !a.Revoked {
1287				amounts = append(amounts, a.Amount)
1288			}
1289		}
1290		net, err = sumSigned64(amounts...)
1291		if err != nil {
1292			return 0, 0, err
1293		}
1294		payable, err = addSigned64(b.TotalFee, net)
1295		if err != nil {
1296			return 0, 0, err
1297		}
1298		if payable < 0 {
1299			return 0, 0, errPayableOutOfRange
1300		}
1301		return net, payable, nil
1302	}
1303

