228			return err
229		}
230	
231		s, err := loadStore(dir)
232		if err != nil {
233			return err
234		}
235		if _, exists := s.Customers[id]; exists {
236			return fmt.Errorf("客户标识 %q 已存在，客户单价创建后不可修改", id)
