246	func parsePrice(text string) (int64, error) {
247		text = strings.TrimSpace(text)
248		price, err := strconv.ParseInt(text, 10, 64)
249		if err != nil {
250			return 0, fmt.Errorf("单价 %q 不是有符号 64 位整数范围内的整数: %w", text, err)
251		}
252		if price < 0 {
253			return 0, fmt.Errorf("单价必须是非负整数分，收到 %d", price)
254		}
255		return price, nil
256	}
