258	// parsedRow 是导入文件中一行解析后的候选用量。
259	type parsedRow struct {
260		line int // 文件中的行号（含表头），用于报错定位
261		rec  usageRecord
262		t    time.Time
263	}
264	
265	func cmdUsageImport(dir, file string) error {
266		var reader io.ReadCloser
267		var source string
268		if file == "-" {
269			reader = io.NopCloser(os.Stdin)
270			source = "标准输入"
271		} else {
272			f, err := os.Open(file)
273			if err != nil {
274				return fmt.Errorf("无法打开用量文件 %s: %w", file, err)
275			}
276			reader = f
277			source = file
278		}
279		defer reader.Close()
280	
281		rows, parseErrs := parseUsageFile(reader)
282	
283		s, err := loadStore(dir)
284		if err != nil {
285			return err
286		}
287	
288		// 先校验：任何问题都在此阶段收集，全部通过后才一次性修改并保存，
289		// 保证“整批导入先校验再生效”，失败不留下任何新用量。
290		var problems []string
291		problems = append(problems, parseErrs...)
292	
293		accepted := make(map[string]*parsedRow) // 本批内首次出现、内容确定的记录
294		var ordered []*parsedRow
295		newCount, dupCount := 0, 0
296	
297		for _, r := range rows {
298			cust, ok := s.Customers[r.rec.CustomerID]
299			if !ok {
300				problems = append(problems, fmt.Sprintf("第 %d 行：客户标识 %q 不存在", r.line, r.rec.CustomerID))
301				continue
302			}
303	
304			// 去重判定同时对“库中已有”和“本文件内已出现”生效，且先于暂停、
305			// 封账与金额预检：已存在记录（含已撤回记录）按客户、解析后的时间点
306			// 和数量与原内容判重，相同重放计入重复跳过——即使该月后来已封账、
307			// 暂停或后续方案计价会溢出也不受阻；已撤回记录的重放不会恢复记录。
308			var existing *usageRecord
309			if inStore, ok := s.Usage[r.rec.ID]; ok {
310				existing = inStore
311			} else if inBatch, ok := accepted[r.rec.ID]; ok {
312				existing = &inBatch.rec
313			}
314			if existing != nil {
315				if !sameUsage(existing, &r.rec, r.t) {
316					problems = append(problems, fmt.Sprintf("第 %d 行：用量标识 %q 已存在但内容不同（已有客户=%s 时间=%s 数量=%d）",
317						r.line, r.rec.ID, existing.CustomerID, existing.Time, existing.Quantity))
318					continue
319				}
320				dupCount++
321				continue
322			}
323	
324			// 以下为全新用量：暂停、封账及当前方案下金额预检只约束全新用量。
325			// 暂停月的新用量一律拒绝：按记录时间换算的 UTC 月份判断，处于任一
326			// 暂停区间（含起月、不含结束月）即整批失败并指出行号。
327			rowMonth := r.t.UTC().Format("2006-01")
328			if s.isSuspendedMonth(r.rec.CustomerID, rowMonth) {
329				problems = append(problems, fmt.Sprintf("第 %d 行：客户 %s 的 %s 处于暂停区间，暂停服务期间不接收用量（新用量 %q 被拒绝）",
330					r.line, r.rec.CustomerID, rowMonth, r.rec.ID))
331				continue
332			}
333			// 金额可行性预检：固定单价客户检查 数量×单价；阶梯客户按记录时间
334			// 换算的 UTC 月份的有效方案，以单条数量从零计价，检查分段金额不
335			// 溢出（金额单位：分）。
336			if cust.PlanID == "" {
337				if _, err := mul64(r.rec.Quantity, cust.Price); err != nil {
338					problems = append(problems, fmt.Sprintf("第 %d 行：数量 %d × 单价 %d 金额溢出有符号 64 位整数范围", r.line, r.rec.Quantity, cust.Price))
339					continue
340				}
341			} else {
342				rec := r.rec
343				planID := s.effectivePlanID(cust, rowMonth)
344				if _, err := tieredPrice(s.Plans[planID].Tiers, []*usageRecord{&rec}); err != nil {
345					problems = append(problems, fmt.Sprintf("第 %d 行：按 %s 月有效方案 %q 对单条数量从零计价失败：%v", r.line, rowMonth, planID, err))
346					continue
347				}
348			}
349	
350			// 全新标识：不得进入该客户已封账的 UTC 自然月。
351			if s.sealed(r.rec.CustomerID, rowMonth) {
352				problems = append(problems, fmt.Sprintf("第 %d 行：客户 %s 的 %s 已封账，新用量 %q 不得进入",
353					r.line, r.rec.CustomerID, rowMonth, r.rec.ID))
354				continue
355			}
356	
357			rr := r
358			accepted[r.rec.ID] = rr
359			ordered = append(ordered, rr)
360			newCount++
361		}
362	
363		if len(problems) > 0 {
364			return fmt.Errorf("导入失败，整批未生效（共 %d 个问题）：\n  %s", len(problems), strings.Join(problems, "\n  "))
365		}
366	
367		for _, r := range ordered {
368			rec := r.rec
369			s.Usage[rec.ID] = &rec
370		}
371		if err := s.save(); err != nil {
372			return err
373		}
374		fmt.Fprintf(stdout, "导入完成（%s）：新增 %d 条，重复跳过 %d 条\n", source, newCount, dupCount)
375		return nil
376	}
