378	// parseUsageFile 完整读取 CSV，做格式层面的解析；业务层面的校验在调用方完成。
379	func parseUsageFile(r io.Reader) ([]*parsedRow, []string) {
380		cr := csv.NewReader(r)
381		cr.FieldsPerRecord = 4
382		cr.TrimLeadingSpace = true
383	
384		header, err := cr.Read()
385		if err == io.EOF {
386			return nil, []string{"文件为空：首行必须是表头 " + usageHeader}
387		}
388		if err != nil {
389			return nil, []string{fmt.Sprintf("无法读取表头：%v（首行必须是 %s）", err, usageHeader)}
390		}
391		for i := range header {
392			header[i] = strings.TrimSpace(header[i])
393		}
394		if len(header) != 4 || header[0] != "usage_id" || header[1] != "customer_id" ||
395			header[2] != "time" || header[3] != "quantity" {
396			return nil, []string{fmt.Sprintf("表头必须是 %s，实际为 %s", usageHeader, strings.Join(header, ","))}
397		}
398	
399		var rows []*parsedRow
400		var problems []string
401		line := 1
402		for {
403			rec, err := cr.Read()
404			if err == io.EOF {
405				break
406			}
407			line++
408			if err != nil {
409				problems = append(problems, fmt.Sprintf("第 %d 行：CSV 格式错误：%v", line, err))
410				if pe, ok := err.(*csv.ParseError); ok && pe.Err == csv.ErrFieldCount {
411					// 字段数错误后继续读取仍可能拿到错乱记录，直接终止解析。
412					break
413				}
414				continue
415			}
416			for i := range rec {
417				rec[i] = strings.TrimSpace(rec[i])
418			}
419	
420			id, custID, ts, qtyText := rec[0], rec[1], rec[2], rec[3]
421			if id == "" {
422				problems = append(problems, fmt.Sprintf("第 %d 行：用量标识不能为空", line))
423				continue
424			}
425			if custID == "" {
426				problems = append(problems, fmt.Sprintf("第 %d 行：客户标识不能为空", line))
427				continue
428			}
429			t, err := time.Parse(time.RFC3339, ts)
430			if err != nil {
431				problems = append(problems, fmt.Sprintf("第 %d 行：时间 %q 不是 RFC3339 格式：%v", line, ts, err))
432				continue
433			}
434			qty, err := strconv.ParseInt(qtyText, 10, 64)
435			if err != nil {
436				problems = append(problems, fmt.Sprintf("第 %d 行：数量 %q 不是有符号 64 位整数", line, qtyText))
437				continue
438			}
439			if qty <= 0 {
440				problems = append(problems, fmt.Sprintf("第 %d 行：数量必须是正整数，收到 %d", line, qty))
441				continue
442			}
443	
444			rows = append(rows, &parsedRow{
445				line: line,
446				rec:  usageRecord{ID: id, CustomerID: custID, Time: ts, Quantity: qty},
447				t:    t,
448			})
449		}
450		return rows, problems
451	}
