453	// sameUsage 按（客户、解析后的时间点、数量）判定两条记录内容是否相同，
454	// 时间比较的是瞬间，因此 Z 与 +08:00 表示同一时刻视为相同。
455	func sameUsage(existing *usageRecord, candidate *usageRecord, candidateT time.Time) bool {
456		if existing.CustomerID != candidate.CustomerID || existing.Quantity != candidate.Quantity {
457			return false
458		}
459		et, err := time.Parse(time.RFC3339, existing.Time)
460		if err != nil {
461			return existing.Time == candidate.Time
462		}
463		return et.Equal(candidateT)
464	}
