466	// validMonth 严格校验 YYYY-MM（月份两位、01..12）。
467	func validMonth(m string) bool {
468		t, err := time.Parse("2006-01", m)
469		if err != nil || t.Format("2006-01") != m || t.Year() < 1 {
470			return false
471		}
472		return true
473	}
474	
475	// inMonth 判定一条 RFC3339 时间（换算 UTC 后）是否落在给定自然月。
476	func inMonth(rfc3339, month string) bool {
477		t, err := time.Parse(time.RFC3339, rfc3339)
478		if err != nil {
479			return false
480		}
481		return t.UTC().Format("2006-01") == month
482	}
483	
484	// utcMonth 返回 RFC3339 时间换算 UTC 后的自然月（YYYY-MM）。
485	// 入参时间均已在载入/导入时校验为 RFC3339。
486	func utcMonth(rfc3339 string) string {
487		t, _ := time.Parse(time.RFC3339, rfc3339)
488		return t.UTC().Format("2006-01")
489	}
