491	func cmdBillSettle(dir, customerID, month string) error {
492		if !validMonth(month) {
493			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
494		}
495		s, err := loadStore(dir)
496		if err != nil {
497			return err
498		}
499		cust, ok := s.Customers[customerID]
500		if !ok {
501			return fmt.Errorf("客户标识 %q 不存在", customerID)
502		}
503	
504		// 暂停月无论方案月费多少都拒绝结算：不封账、不生成零金额账单。
505		if s.isSuspendedMonth(customerID, month) {
506			return fmt.Errorf("客户 %s 的 %s 处于暂停区间，暂停服务期间不产生月费账单，拒绝结算且不封账", customerID, month)
507		}
508	
509		key := billKey(customerID, month)
510		if existing, ok := s.Bills[key]; ok {
511			// 幂等：同一客户同一月份重复结算，直接返回原账单，
512			// 不重新计费、不产生新账单或调整、不落盘。
513			fmt.Fprintf(stdout, "客户 %s 的 %s 已结算，返回原账单（幂等，不重新计费）：\n\n", customerID, month)
514			printBill(existing, cust, s)
515			return nil
516		}
517	
518		// 归集该客户 UTC 自然月内的全部有效（未撤回）用量，区间为左闭右开
519		// [月初, 下月初)。有效方案月费大于 0 的阶梯客户即使无用量也须出账
520		// （收取一次整月月费）；月费为 0 的方案与固定单价客户无用量时仍拒绝
521		// 结算且不封账。
522		inMonthRecs := monthUsage(s, customerID, month)
523		if len(inMonthRecs) == 0 && !monthlyFeeBillable(s, cust, month) {
524			return fmt.Errorf("客户 %s 在 %s 没有用量，拒绝结算且不封账", customerID, month)
525		}
526	
527		// 绑定阶梯方案的客户走按月累计分档计价；固定单价客户保持原路径。
528		if cust.PlanID != "" {
529			return settleTiered(s, cust, month, inMonthRecs)
530		}
531	
532		b, err := buildFixedBill(cust, month, inMonthRecs)
533		if err != nil {
534			return fmt.Errorf("%v，拒绝结算且不封账", err)
535		}
536		s.Bills[key] = b
537	
538		// 账单与封账状态在同一次原子保存中一起持久化；保存失败则一切不生效。
539		if err := s.save(); err != nil {
540			delete(s.Bills, key)
541			return err
542		}
543		fmt.Fprintf(stdout, "结算完成，客户 %s 的 %s 已封账：\n\n", customerID, month)
544		printBill(b, cust, s)
545		return nil
546	}
