568	// monthUsage 归集客户在某 UTC 自然月（左闭右开 [月初, 下月初)）内的全部
569	// 有效（未撤回）用量，并按计价顺序（解析后的时间点升序、同一时间按标识
570	// 字典序）排列。已撤回用量不计费用，不参与单笔及批量结算；阶梯计价将剩余
571	// 记录按原有时间点及标识顺序从零累计重新分档。
572	func monthUsage(s *state, customerID, month string) []*usageRecord {
573		var recs []*usageRecord
574		for _, u := range s.Usage {
575			if s.isWithdrawn(u.ID) {
576				continue
577			}
578			if u.CustomerID == customerID && inMonth(u.Time, month) {
579				recs = append(recs, u)
580			}
581		}
582		sortByInstant(recs)
583		return recs
584	}
