586	// buildFixedBill 为固定单价客户构造账单（不落盘）：逐条 数量×单价 并汇总，
587	// 全程整数运算，任何一步溢出都返回错误。recs 须已按计价顺序排列。
588	func buildFixedBill(cust *customer, month string, recs []*usageRecord) (*bill, error) {
589		lines := make([]billLine, 0, len(recs))
590		var totalQty, totalFee int64
591		for _, u := range recs {
592			lineFee, err := mul64(u.Quantity, cust.Price)
593			if err != nil {
594				return nil, fmt.Errorf("用量 %s：数量 %d × 单价 %d 金额溢出", u.ID, u.Quantity, cust.Price)
595			}
596			if totalQty, err = add64(totalQty, u.Quantity); err != nil {
597				return nil, fmt.Errorf("汇总数量溢出有符号 64 位整数范围")
598			}
599			if totalFee, err = add64(totalFee, lineFee); err != nil {
600				return nil, fmt.Errorf("汇总金额溢出有符号 64 位整数范围")
601			}
602			lines = append(lines, billLine{
603				UsageID:  u.ID,
604				Time:     u.Time,
605				Quantity: u.Quantity,
606				LineFee:  lineFee,
607			})
608		}
609		return &bill{
610			ID:         stableBillID(cust.ID, month),
611			CustomerID: cust.ID,
612			Month:      month,
613			TotalQty:   totalQty,
614			UnitPrice:  cust.Price,
615			TotalFee:   totalFee,
616			Lines:      lines,
617			CreatedAt:  time.Now().UTC().Format(time.RFC3339),
618		}, nil
619	}
620	
621	func sortByInstant(us []*usageRecord) {
622		// 入参时间均已在载入/导入时校验为 RFC3339。
623		sort.Slice(us, func(i, j int) bool {
624			ti, _ := time.Parse(time.RFC3339, us[i].Time)
625			tj, _ := time.Parse(time.RFC3339, us[j].Time)
626			ui, uj := ti.UTC(), tj.UTC()
627			if !ui.Equal(uj) {
628				return ui.Before(uj)
629			}
630			return us[i].ID < us[j].ID
631		})
632	}
