654			for i, t := range b.PlanTiers {
655				if t.Limit == 0 {
656					fmt.Fprintf(stdout, "  第 %d 档：累计数量无上限，单价 %d 分（%s）\n", i+1, t.Price, moneyFen(t.Price))
657				} else {
658					fmt.Fprintf(stdout, "  第 %d 档：累计上限 %d，单价 %d 分（%s）\n", i+1, t.Limit, t.Price, moneyFen(t.Price))
659				}
660			}
661		} else {
662			fmt.Fprintf(stdout, "单价：%d 分（%s）\n", b.UnitPrice, moneyFen(b.UnitPrice))
663		}
664		fmt.Fprintf(stdout, "总数量：%d\n", b.TotalQty)
665		if tiered {
666			// 阶梯账单分列月费与用量费：原总金额 = 月费 + 全月用量费；
667			// 月费不计入总数量、各档金额或逐条小计。
668			usageFee := b.TotalFee - b.MonthlyFee
669			fmt.Fprintf(stdout, "月费：%d 分（%s，整月收取，不按天折算）\n", b.MonthlyFee, moneyFen(b.MonthlyFee))
670			fmt.Fprintf(stdout, "用量费：%d 分（%s）\n", usageFee, moneyFen(usageFee))
671			fmt.Fprintf(stdout, "原总金额：%d 分（%s，月费加全月用量费）\n", b.TotalFee, moneyFen(b.TotalFee))
672		} else {
673			fmt.Fprintf(stdout, "总金额：%d 分（%s）\n", b.TotalFee, moneyFen(b.TotalFee))
674		}
675		if tiered {
676			fmt.Fprintln(stdout, "各档合计：")
677			for i, tt := range b.TierTotals {
678				fmt.Fprintf(stdout, "  第 %d 档：数量 %d，单价 %d 分，金额 %d 分（%s）\n",
679					i+1, tt.Quantity, b.PlanTiers[i].Price, tt.Fee, moneyFen(tt.Fee))
680			}
681		}
682		// 数据在载入时已校验一致，此处计算不会出错。
683		net, payable, _ := billTotals(b, adjs)
684		received, _ := paymentReceived(s, b.CustomerID, b.Month)
685		outstanding := payable - received // 不变量保证 0 ≤ 实收 ≤ 当前应付
686		fmt.Fprintf(stdout, "调整净额：%+d 分（%s）\n", net, moneyFen(net))
687		fmt.Fprintf(stdout, "当前应付：%d 分（%s）\n", payable, moneyFen(payable))
688		fmt.Fprintf(stdout, "实收：%d 分（%s）\n", received, moneyFen(received))
689		fmt.Fprintf(stdout, "未收余额：%d 分（%s）\n", outstanding, moneyFen(outstanding))
690		if len(b.Lines) == 0 {
691			fmt.Fprintln(stdout, "明细：无（本账期无用量，仅收取月费）")
692		} else {
693			fmt.Fprintln(stdout, "明细：")
694		}
695		for i, ln := range b.Lines {
696			fmt.Fprintf(stdout, "  %d. 用量标识=%s 时间=%s 数量=%d 小计=%d 分（%s）\n",
697				i+1, ln.UsageID, ln.Time, ln.Quantity, ln.LineFee, moneyFen(ln.LineFee))
698			// 阶梯账单逐条展示跨档分段的数量、单价与小计。
699			for j, seg := range ln.Segments {
700				fmt.Fprintf(stdout, "     分段 %d：第 %d 档 数量=%d 单价=%d 分 小计=%d 分（%s）\n",
701					j+1, seg.Tier+1, seg.Quantity, b.PlanTiers[seg.Tier].Price, seg.Fee, moneyFen(seg.Fee))
702			}
703		}
704		if len(adjs) == 0 {
705			fmt.Fprintln(stdout, "调整与撤销历史：无")
706		} else {
707			fmt.Fprintln(stdout, "调整与撤销历史（按成功操作顺序）：")
708			for i, ev := range historyEvents(adjs) {
709				fmt.Fprintf(stdout, "  %d. %s\n", i+1, ev)
710			}
711		}
712		if len(pays) == 0 {
713			fmt.Fprintln(stdout, "收款与撤销历史：无")
714		} else {
715			fmt.Fprintln(stdout, "收款与撤销历史（按成功操作顺序）：")
716			for i, ev := range paymentHistoryEvents(s, pays, b.Month) {
717				fmt.Fprintf(stdout, "  %d. %s\n", i+1, ev)
718			}
719		}
720	}
