722	// historyEvents 把调整与撤销展开为按操作序号排序的可读历史条目。
723	func historyEvents(adjs []*adjustment) []string {
724		type event struct {
725			seq  int64
726			text string
727		}
728		var events []event
729		for _, a := range adjs {
730			events = append(events, event{a.Seq, fmt.Sprintf("调整 %s：%s %+d 分（%s），原因：%s，当前状态：%s",
731				a.ID, adjustKind(a.Amount), a.Amount, moneyFen(a.Amount), a.Reason, adjustStatus(a))})
732			if a.Revoked {
733				events = append(events, event{a.RevokeSeq, fmt.Sprintf("撤销 %s：原因：%s（关联调整 %s 的%s %+d 分）",
734					a.ID, a.RevokeReason, a.ID, adjustKind(a.Amount), a.Amount)})
735			}
736		}
737		sort.Slice(events, func(i, j int) bool { return events[i].seq < events[j].seq })
738		out := make([]string, len(events))
739		for i, ev := range events {
740			out[i] = ev.text
741		}
742		return out
743	}
744	
745	func adjustKind(amount int64) string {
746		if amount > 0 {
747			return "补收"
748		}
749		return "减免"
750	}
751	
752	func adjustStatus(a *adjustment) string {
753		if a.Revoked {
754			return "已撤销"
755		}
756		return "生效中"
757	}
