759	// paymentHistoryEvents 把收款登记、分配更正与撤销展开为按操作序号排序的
760	// 可读历史条目；month 为当前展示账单所在月份。收款事件展示首次登记时在
761	// 本账单的分配，更正事件展示本账单分配的前后变化，撤销事件展示被整笔取消
762	// 的最新分配。
763	func paymentHistoryEvents(s *state, pays []*payment, month string) []string {
764		type event struct {
765			seq  int64
766			text string
767		}
768		var events []event
769		for _, p := range pays {
770			alloc := p.amountFor(month)
771			events = append(events, event{p.Seq, fmt.Sprintf("收款 %s：总额 %d 分（%s），本账单分配 %d 分（%s），备注：%s，当前状态：%s（客户 %s）",
772				p.ID, p.Total, moneyFen(p.Total), alloc, moneyFen(alloc), p.Note, paymentStatus(p), p.CustomerID)})
773			// 以首次登记分配为起点，按序号回放该收款在本账单的分配变化。
774			running := alloc
775			for _, c := range correctionsFor(s, p.ID) {
776				after := allocAmountFor(c.Allocations, month)
777				if running == 0 && after == 0 {
778					continue // 本次更正不涉及本账单
779				}
780				events = append(events, event{c.Seq, fmt.Sprintf("更正 %s：原因：%s（关联收款 %s，本账单分配 %d 分 → %d 分）",
781					c.ID, c.Reason, p.ID, running, after)})
782				running = after
783			}
784			if p.Revoked {
785				// 整笔撤销取消的是撤销时的最新分配。
786				events = append(events, event{p.RevokeSeq, fmt.Sprintf("撤销收款 %s：原因：%s（关联收款 %s，总额 %d 分，本账单分配 %d 分）",
787					p.ID, p.RevokeReason, p.ID, p.Total, running)})
788			}
789			// 退款在其发生序号减少本账单实收；退款不可撤销，记录永久保留。
790			for _, r := range refundsFor(s, p.ID) {
791				amt := allocAmountFor(r.Allocations, month)
792				if amt <= 0 {
793					continue // 本次退款不涉及本账单
794				}
795				events = append(events, event{r.Seq, fmt.Sprintf("退款 %s：原因：%s（关联收款 %s，本账单退款 %d 分（%s））",
796					r.ID, r.Reason, p.ID, amt, moneyFen(amt))})
797			}
798		}
799		sort.Slice(events, func(i, j int) bool { return events[i].seq < events[j].seq })
800		out := make([]string, len(events))
801		for i, ev := range events {
802			out[i] = ev.text
803		}
804		return out
805	}
