814	// parseAmount 解析调整金额：有符号 64 位整数、非零（正数补收、负数减免）。
815	func parseAmount(text string) (int64, error) {
816		text = strings.TrimSpace(text)
817		amount, err := strconv.ParseInt(text, 10, 64)
818		if err != nil {
819			return 0, fmt.Errorf("调整金额 %q 不是有符号 64 位整数范围内的整数: %w", text, err)
820		}
821		if amount == 0 {
822			return 0, fmt.Errorf("调整金额不能为零分（正数补收、负数减免）")
823		}
824		return amount, nil
825	}
