827	func cmdBillAdjust(dir, customerID, month, adjID, amountText, reason string) error {
828		if !validMonth(month) {
829			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
830		}
831		if strings.TrimSpace(adjID) == "" {
832			return fmt.Errorf("调整标识不能为空")
833		}
834		amount, err := parseAmount(amountText)
835		if err != nil {
836			return err
837		}
838		if strings.TrimSpace(reason) == "" {
839			return fmt.Errorf("调整原因不能为空")
840		}
841	
842		s, err := loadStore(dir)
843		if err != nil {
844			return err
845		}
846		if _, ok := s.Customers[customerID]; !ok {
847			return fmt.Errorf("客户标识 %q 不存在", customerID)
848		}
849		b, ok := s.Bills[billKey(customerID, month)]
850		if !ok {
851			return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算），费用调整只能作用于已存在账单", customerID, month)
852		}
853	
854		if existing, ok := s.Adjustments[adjID]; ok {
855			// 相同标识按客户、月份、金额、原因判断重复：内容相同返回已保存
856			// 记录，不再次增减应付；已撤销的重放仍返回已撤销状态，不重新生效。
857			if existing.CustomerID == customerID && existing.Month == month &&
858				existing.Amount == amount && existing.Reason == reason {
859				fmt.Fprintf(stdout, "调整 %q 已存在且内容相同，返回已保存记录（不重复增减应付）：\n\n", adjID)
860				printAdjustment(existing, s)
861				return nil
862			}
863			return fmt.Errorf("调整标识 %q 已存在但内容不同（已有：客户=%s 月份=%s 金额=%d 原因=%q），拒绝复用",
864				adjID, existing.CustomerID, existing.Month, existing.Amount, existing.Reason)
865		}
866	
867		// 应付可行性预检：原总金额 + 全部未撤销调整 + 本次金额必须落在
868		// [0, 有符号 64 位最大值] 内，且不得低于已登记实收，否则拒绝且
869		// 不占用该调整标识。
870		_, payable, err := billTotals(b, adjustmentsFor(s, customerID, month))
871		if err != nil {
872			return fmt.Errorf("账单当前应付异常，拒绝调整: %w", err)
873		}
874		received, err := paymentReceived(s, customerID, month)
875		if err != nil {
876			return fmt.Errorf("实收累计异常，拒绝调整: %w", err)
877		}
878		newPayable, err := addSigned64(payable, amount)
879		if err != nil {
880			return fmt.Errorf("调整后当前应付超出有符号 64 位最大值（当前 %d 分，本次 %+d 分），拒绝调整", payable, amount)
881		}
882		if newPayable < 0 {
883			return fmt.Errorf("调整后当前应付将为 %d 分（小于 0，当前 %d 分，本次 %+d 分），拒绝调整", newPayable, payable, amount)
884		}
885		if newPayable < received {
886			return fmt.Errorf("调整后当前应付 %d 分将低于实收 %d 分（当前 %d 分，本次 %+d 分），拒绝调整；可先撤销误登记的收款再重试",
887				newPayable, received, payable, amount)
888		}
889	
890		a := &adjustment{
891			ID:         adjID,
892			CustomerID: customerID,
893			Month:      month,
894			Amount:     amount,
895			Reason:     reason,
896			CreatedAt:  time.Now().UTC().Format(time.RFC3339),
897		}
898		s.NextSeq++
899		a.Seq = s.NextSeq
900		s.Adjustments[adjID] = a
901	
902		// 调整记录与序号在同一次原子保存中持久化；保存失败则一切不生效，
903		// 该调整标识不被占用。
904		if err := s.save(); err != nil {
905			delete(s.Adjustments, adjID)
906			s.NextSeq--
907			return err
908		}
909		fmt.Fprintf(stdout, "已登记%s调整 %q，客户 %s 的 %s 当前应付 %d 分（%s）：\n\n",
910			adjustKind(amount), adjID, customerID, month, newPayable, moneyFen(newPayable))
911		printAdjustment(a, s)
912		return nil
913	}
