915	func cmdBillRevoke(dir, adjID, reason string) error {
916		if strings.TrimSpace(adjID) == "" {
917			return fmt.Errorf("调整标识不能为空")
918		}
919		if strings.TrimSpace(reason) == "" {
920			return fmt.Errorf("撤销原因不能为空")
921		}
922	
923		s, err := loadStore(dir)
924		if err != nil {
925			return err
926		}
927		a, ok := s.Adjustments[adjID]
928		if !ok {
929			return fmt.Errorf("调整标识 %q 不存在，无法撤销", adjID)
930		}
931	
932		if a.Revoked {
933			// 相同标识与相同原因重复撤销：幂等成功，不新增记录；
934			// 改用其他原因则拒绝。
935			if a.RevokeReason == reason {
936				fmt.Fprintf(stdout, "调整 %q 已撤销且撤销原因相同，幂等返回（不新增记录）：\n\n", adjID)
937				printAdjustment(a, s)
938				return nil
939			}
940			return fmt.Errorf("调整 %q 已撤销（撤销原因 %q），改用其他原因重复撤销被拒绝", adjID, a.RevokeReason)
941		}
942	
943		// 撤销只取消该笔调整的金额影响；若撤销后当前应付越界或低于实收则
944		// 拒绝，该调整仍保持有效，可先撤销误登记的收款或在其他合法调整
945		// 改变余额后重试。
946		b := s.Bills[billKey(a.CustomerID, a.Month)] // 载入时已校验存在
947		_, payable, err := billTotals(b, adjustmentsFor(s, a.CustomerID, a.Month))
948		if err != nil {
949			return fmt.Errorf("账单当前应付异常，拒绝撤销: %w", err)
950		}
951		received, err := paymentReceived(s, a.CustomerID, a.Month)
952		if err != nil {
953			return fmt.Errorf("实收累计异常，拒绝撤销: %w", err)
954		}
955		neg, err := neg64(a.Amount)
956		if err != nil {
957			return fmt.Errorf("撤销后当前应付将超出有符号 64 位最大值，拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试")
958		}
959		newPayable, err := addSigned64(payable, neg)
960		if err != nil {
961			return fmt.Errorf("撤销后当前应付将超出有符号 64 位最大值（当前 %d 分，取消 %+d 分），拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试",
962				payable, a.Amount)
963		}
964		if newPayable < 0 {
965			return fmt.Errorf("撤销后当前应付将为 %d 分（小于 0，当前 %d 分，取消 %+d 分），拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试",
966				newPayable, payable, a.Amount)
967		}
968		if newPayable < received {
969			return fmt.Errorf("撤销后当前应付 %d 分将低于实收 %d 分（当前 %d 分，取消 %+d 分），拒绝撤销；可先撤销误登记的收款再重试",
970				newPayable, received, payable, a.Amount)
971		}
972	
973		a.Revoked = true
974		a.RevokeReason = reason
975		a.RevokedAt = time.Now().UTC().Format(time.RFC3339)
976		s.NextSeq++
977		a.RevokeSeq = s.NextSeq
978	
979		// 撤销信息与原记录在同一次原子保存中持久化；保存失败则一切不生效。
980		if err := s.save(); err != nil {
981			a.Revoked = false
982			a.RevokeReason = ""
983			a.RevokedAt = ""
984			a.RevokeSeq = 0
985			s.NextSeq--
986			return err
987		}
988		fmt.Fprintf(stdout, "已撤销调整 %q（%s %+d 分），客户 %s 的 %s 当前应付 %d 分（%s）：\n\n",
989			adjID, adjustKind(a.Amount), a.Amount, a.CustomerID, a.Month, newPayable, moneyFen(newPayable))
990		printAdjustment(a, s)
991		return nil
992	}
