994	// printAdjustment 输出单笔调整记录及其当前状态；payable 取自当前库状态。
995	func printAdjustment(a *adjustment, s *state) {
996		b := s.Bills[billKey(a.CustomerID, a.Month)]
997		_, payable, _ := billTotals(b, adjustmentsFor(s, a.CustomerID, a.Month))
998		fmt.Fprintf(stdout, "调整标识：%s\n", a.ID)
999		fmt.Fprintf(stdout, "客户：%s\n", a.CustomerID)
1000		fmt.Fprintf(stdout, "月份：%s\n", a.Month)
