1002		fmt.Fprintf(stdout, "原因：%s\n", a.Reason)
1003		if a.Revoked {
1004			fmt.Fprintf(stdout, "当前状态：已撤销（撤销原因：%s）\n", a.RevokeReason)
1005		} else {
1006			fmt.Fprintf(stdout, "当前状态：生效中\n")
1007		}
1008		fmt.Fprintf(stdout, "当前应付：%d 分（%s）\n", payable, moneyFen(payable))
1009	}
