1011	// parsePositiveAmount 解析收款金额：正整数分（不接受零、负数、小数）。
1012	func parsePositiveAmount(text string) (int64, error) {
1013		text = strings.TrimSpace(text)
1014		amount, err := strconv.ParseInt(text, 10, 64)
1015		if err != nil {
1016			return 0, fmt.Errorf("收款金额 %q 不是有符号 64 位整数范围内的整数: %w", text, err)
1017		}
1018		if amount <= 0 {
1019			return 0, fmt.Errorf("收款金额必须是正整数分，收到 %d", amount)
1020		}
1021		return amount, nil
1022	}
