1037	func cmdBillRemit(dir, customerID, payID, totalText, note string, allocArgs []string) error {
1038		total, err := parsePositiveAmount(totalText)
1039		if err != nil {
1040			return err
1041		}
1042		allocs, err := parseAllocations(allocArgs)
1043		if err != nil {
1044			return err
1045		}
1046		// 分配合计必须等于总额，全程整数运算，溢出拒绝。
1047		var sum int64
1048		for _, al := range allocs {
1049			sum, err = add64(sum, al.Amount)
1050			if err != nil {
1051				return fmt.Errorf("分配金额合计溢出有符号 64 位整数范围，拒绝登记")
1052			}
1053		}
1054		if sum != total {
1055			return fmt.Errorf("分配合计 %d 分与收款总额 %d 分不一致，拒绝登记", sum, total)
1056		}
1057		return registerPayment(dir, customerID, payID, total, note, allocs)
1058	}
