1060	// --- 自动分配汇款（bill remit-auto） ---
1061	
1062	// cmdBillRemitAuto 登记一笔自动分配汇款：调用方只提供客户、收款标识、总金额
1063	// 与备注，月份金额由工具确定——首次登记只选择该客户当前已有账单，按 UTC
1064	// 账期月升序依次偿还当前未收余额（调整、最新收款分配、撤销及退款后的净额），
1065	// 跳过余额为 0 的月份，前一月份还清后才分配下一月，最后一月可部分偿还；
1066	// 不补结算、不跨客户、不留未分配款项。无欠款或总金额超过全部欠款时整笔拒绝。
1067	func cmdBillRemitAuto(dir, customerID, payID, totalText, note string) error {
1068		total, err := parsePositiveAmount(totalText)
1069		if err != nil {
1070			return err
1071		}
1072		if strings.TrimSpace(payID) == "" {
1073			return fmt.Errorf("收款标识不能为空")
1074		}
1075		if strings.TrimSpace(note) == "" {
1076			return fmt.Errorf("收款备注不能为空")
1077		}
1078	
1079		s, err := loadStore(dir)
1080		if err != nil {
1081			return err
1082		}
1083		if _, ok := s.Customers[customerID]; !ok {
1084			return fmt.Errorf("客户标识 %q 不存在", customerID)
1085		}
1086	
1087		if existing, ok := s.Payments[payID]; ok {
1088			// 自动登记按客户、总金额、备注判重：相同请求返回原收款及当前状态，
1089			// 不写盘、不重新分配、不增加序号；已撤销或已退款的仍返回当前状态，
1090			// 不恢复旧分配或已退、已撤销金额。
1091			if existing.Auto && existing.CustomerID == customerID &&
1092				existing.Total == total && existing.Note == note {
1093				fmt.Fprintf(stdout, "收款 %q 已存在且内容相同（自动分配登记），返回原收款及当前状态（不写盘、不重新分配、不增加序号）：\n\n", payID)
1094				printAutoPayment(s, existing)
1095				return nil
1096			}
1097			// 同一标识在自动与显式分配登记间复用拒绝；内容不同同样拒绝。
1098			if !existing.Auto {
1099				return fmt.Errorf("收款标识 %q 已由显式分配登记占用（已有：客户=%s 总额=%d 备注=%q 分配=%s），自动与显式分配登记之间不得复用，拒绝",
1100					payID, existing.CustomerID, existing.Total, existing.Note, formatAllocations(existing.Allocations))
1101			}
1102			return fmt.Errorf("收款标识 %q 已存在但内容不同（已有：客户=%s 总额=%d 备注=%q），拒绝复用",
1103				payID, existing.CustomerID, existing.Total, existing.Note)
1104		}
1105	
1106		// 首次登记：归集该客户当前已有账单的月份，按 UTC 账期月升序排列
1107		// （YYYY-MM 字典序即时间序）。不补结算，只有已存在账单参与分配。
1108		var months []string
1109		for _, b := range s.Bills {
1110			if b.CustomerID == customerID {
1111				months = append(months, b.Month)
1112			}
1113		}
1114		sort.Strings(months)
1115	
1116		// 依次偿还当前未收余额：跳过余额为 0 的月份，前一月份还清后才分配
1117		// 下一月，最后一月可部分偿还。每月未收余额 = 当前应付 − 实收，均在
1118		// [0, 有符号 64 位最大值] 内；remaining 从总额（正整数分）起只减不增，
1119		// 各月余额与分配全程整数计算——即使全部账单欠款合计超过 64 位上限，
1120		// 分配过程也只涉及不超过总额的中间值，不会误拒合法金额。
1121		remaining := total
1122		var allocs []paymentAllocation
1123		for _, m := range months {
1124			if remaining == 0 {
1125				break
1126			}
1127			b := s.Bills[billKey(customerID, m)]
1128			_, payable, err := billTotals(b, adjustmentsFor(s, customerID, m))
1129			if err != nil {
1130				return fmt.Errorf("客户 %s 的 %s 当前应付异常，拒绝登记收款: %w", customerID, m, err)
1131			}
1132			received, err := paymentReceived(s, customerID, m)
1133			if err != nil {
1134				return fmt.Errorf("客户 %s 的 %s 实收累计溢出有符号 64 位整数范围，拒绝登记收款: %w", customerID, m, err)
1135			}
1136			outstanding := payable - received // 不变量保证 0 ≤ 实收 ≤ 当前应付
1137			if outstanding <= 0 {
1138				continue // 跳过余额为 0 的月份
1139			}
1140			amt := outstanding
1141			if amt > remaining {
1142				amt = remaining // 最后一月可部分偿还
1143			}
1144			allocs = append(allocs, paymentAllocation{Month: m, Amount: amt})
1145			remaining -= amt
1146		}
1147		if len(allocs) == 0 {
1148			return fmt.Errorf("客户 %s 当前没有欠款（全部已存在账单的未收余额均为 0），整笔拒绝；不补结算、不跨客户、不留未分配款项", customerID)
1149		}
1150		if remaining > 0 {
1151			return fmt.Errorf("收款总额 %d 分超过客户 %s 全部已存在账单的欠款合计 %d 分，整笔拒绝；不补结算、不跨客户、不留未分配款项",
1152				total, customerID, total-remaining)
1153		}
1154	
1155		// 成功保存为一笔普通收款及首次自动分配：占用一个账后全局序号，
1156		// 不按月份拆成多笔；可沿用分配更正、整笔撤销、部分退款及退款后
1157		// 固定分配的规则。
1158		p := &payment{
1159			ID:          payID,
1160			CustomerID:  customerID,
1161			Total:       total,
1162			Note:        note,
1163			Allocations: allocs,
1164			Auto:        true,
1165			CreatedAt:   time.Now().UTC().Format(time.RFC3339),
1166		}
1167		s.NextSeq++
1168		p.Seq = s.NextSeq
1169		s.Payments[payID] = p
1170	
1171		// 收款记录、首次分配与序号在同一次原子保存中持久化；保存失败则一切
1172		// 不生效，该收款标识与序号不被占用，可原样重试。
1173		if err := s.save(); err != nil {
1174			delete(s.Payments, payID)
1175			s.NextSeq--
1176			return err
1177		}
1178		fmt.Fprintf(stdout, "已按最早欠款账期自动分配并登记收款 %q（总额 %d 分，%s；一次操作，占用一个账后序号）：\n\n",
1179			payID, total, moneyFen(total))
1180		printAutoPayment(s, p)
1181		return nil
1182	}
1183	
1184	// printAutoPayment 输出一笔自动分配登记的收款：收款标识、总额、备注、当前
1185	// 状态、首次分配与最新分配，以及这两份分配所涉月份的当前余额。首次分配
1186	// 永久保留；最新分配经更正变化时以最新为准，退款与撤销不改变首次分配。
1187	func printAutoPayment(s *state, p *payment) {
1188		current := currentAllocations(s, p)
1189		fmt.Fprintf(stdout, "收款标识：%s\n", p.ID)
1190		fmt.Fprintf(stdout, "客户：%s\n", p.CustomerID)
1191		fmt.Fprintf(stdout, "收款总额：%d 分（%s）\n", p.Total, moneyFen(p.Total))
1192		fmt.Fprintf(stdout, "备注：%s\n", p.Note)
1193		if p.Revoked {
1194			fmt.Fprintf(stdout, "当前状态：已撤销（撤销原因：%s）\n", p.RevokeReason)
1195		} else {
1196			fmt.Fprintf(stdout, "当前状态：实收中\n")
1197		}
1198		fmt.Fprintf(stdout, "首次分配（登记时按最早欠款账期自动确定，永久保留）：%s\n", formatAllocations(p.Allocations))
1199		if sameAllocations(current, p.Allocations) {
1200			fmt.Fprintf(stdout, "最新分配：%s（与首次分配相同）\n", formatAllocations(current))
1201		} else {
1202			fmt.Fprintf(stdout, "最新分配（经更正，以最新为准）：%s\n", formatAllocations(current))
1203		}
1204		fmt.Fprintln(stdout, "首次与最新分配所涉月份当前余额：")
1205		for _, m := range unionMonths(p.Allocations, current) {
1206			b := s.Bills[billKey(p.CustomerID, m)] // 载入时已校验存在
1207			_, payable, _ := billTotals(b, adjustmentsFor(s, p.CustomerID, m))
1208			received, _ := paymentReceived(s, p.CustomerID, m)
1209			fmt.Fprintf(stdout, "  月份 %s：首次分配 %d 分，最新分配 %d 分；当前应付 %d 分（%s），实收 %d 分（%s），未收余额 %d 分（%s）\n",
1210				m, allocAmountFor(p.Allocations, m), allocAmountFor(current, m),
1211				payable, moneyFen(payable), received, moneyFen(received), payable-received, moneyFen(payable-received))
1212		}
1213	}
1214	
1215	// parseAllocations 解析 <YYYY-MM:金额分> 形式的分配列表：至少一项，
1216	// 月份不得重复，每项金额为正整数分。
1217	func parseAllocations(args []string) ([]paymentAllocation, error) {
1218		if len(args) == 0 {
1219			return nil, fmt.Errorf("分配列表不能为空，至少需要一项 <YYYY-MM:金额分>")
1220		}
1221		seen := make(map[string]bool)
1222		allocs := make([]paymentAllocation, 0, len(args))
1223		for _, arg := range args {
1224			parts := strings.Split(arg, ":")
1225			if len(parts) != 2 {
1226				return nil, fmt.Errorf("分配项 %q 格式非法，应为 YYYY-MM:金额分（如 2026-09:500）", arg)
1227			}
1228			month := strings.TrimSpace(parts[0])
1229			if !validMonth(month) {
1230				return nil, fmt.Errorf("分配项 %q 的月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", arg, parts[0])
1231			}
1232			if seen[month] {
1233				return nil, fmt.Errorf("分配月份 %s 重复，拒绝登记", month)
1234			}
1235			seen[month] = true
1236			amount, err := parsePositiveAmount(parts[1])
1237			if err != nil {
1238				return nil, fmt.Errorf("分配项 %q 的金额无效: %w", arg, err)
1239			}
1240			allocs = append(allocs, paymentAllocation{Month: month, Amount: amount})
1241		}
1242		return allocs, nil
1243	}
