1245	// registerPayment 是 bill pay 与 bill remit 共用的收款登记核心：
1246	// 先整体校验再整笔生效，任何一项不合法都不落盘、不占用收款标识。
1247	func registerPayment(dir, customerID, payID string, total int64, note string, allocs []paymentAllocation) error {
1248		if strings.TrimSpace(payID) == "" {
1249			return fmt.Errorf("收款标识不能为空")
1250		}
1251		if strings.TrimSpace(note) == "" {
1252			return fmt.Errorf("收款备注不能为空")
1253		}
1254		// 分配顺序不影响收款身份：统一按月份升序保存与比较。
1255		sort.Slice(allocs, func(i, j int) bool { return allocs[i].Month < allocs[j].Month })
1256	
1257		s, err := loadStore(dir)
1258		if err != nil {
1259			return err
1260		}
1261		if _, ok := s.Customers[customerID]; !ok {
1262			return fmt.Errorf("客户标识 %q 不存在", customerID)
1263		}
1264		for _, al := range allocs {
1265			if _, ok := s.Bills[billKey(customerID, al.Month)]; !ok {
1266				return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算），收款只能登记到已存在账单", customerID, al.Month)
1267			}
1268		}
1269	
1270		if existing, ok := s.Payments[payID]; ok {
1271			// 自动与显式分配登记之间不得复用同一收款标识：标识由 bill remit-auto
1272			// 占用时，bill pay / bill remit 一律拒绝（即使内容碰巧相同）。
1273			if existing.Auto {
1274				return fmt.Errorf("收款标识 %q 已由自动分配登记占用（已有：客户=%s 总额=%d 备注=%q 分配=%s），自动与显式分配登记之间不得复用，拒绝",
1275					payID, existing.CustomerID, existing.Total, existing.Note, formatAllocations(existing.Allocations))
1276			}
1277			// 相同标识按客户、总额、备注与月份-金额对应关系判断重复：内容相同
1278			// 返回已保存记录，不再次计入实收，也不受当前余额变化影响；
1279			// 已撤销的重放仍返回已撤销状态，不恢复实收。
1280			if samePaymentContent(existing, customerID, total, note, allocs) {
1281				fmt.Fprintf(stdout, "收款 %q 已存在且内容相同，返回已保存记录（不重复计入实收）：\n\n", payID)
1282				printPayment(existing, s)
1283				return nil
1284			}
1285			return fmt.Errorf("收款标识 %q 已存在但内容不同（已有：客户=%s 总额=%d 备注=%q 分配=%s），拒绝复用",
1286				payID, existing.CustomerID, existing.Total, existing.Note, formatAllocations(existing.Allocations))
1287		}
1288	
1289		// 首次登记：每项分配不得超过对应账单的未收余额，全部合法才整笔生效。
1290		for _, al := range allocs {
1291			b := s.Bills[billKey(customerID, al.Month)]
1292			_, payable, err := billTotals(b, adjustmentsFor(s, customerID, al.Month))
1293			if err != nil {
1294				return fmt.Errorf("客户 %s 的 %s 当前应付异常，拒绝登记收款: %w", customerID, al.Month, err)
1295			}
1296			received, err := paymentReceived(s, customerID, al.Month)
1297			if err != nil {
1298				return fmt.Errorf("客户 %s 的 %s 实收累计溢出有符号 64 位整数范围，拒绝登记收款: %w", customerID, al.Month, err)
1299			}
1300			if payable == 0 {
1301				return fmt.Errorf("客户 %s 的 %s 当前应付为 0 分，不能登记正额收款", customerID, al.Month)
1302			}
1303			if al.Amount > payable-received {
1304				return fmt.Errorf("分配 %d 分超过未收余额 %d 分（客户 %s 的 %s：当前应付 %d 分，实收 %d 分），拒绝登记",
1305					al.Amount, payable-received, customerID, al.Month, payable, received)
1306			}
1307		}
1308	
1309		p := &payment{
1310			ID:          payID,
1311			CustomerID:  customerID,
1312			Total:       total,
1313			Note:        note,
1314			Allocations: allocs,
1315			CreatedAt:   time.Now().UTC().Format(time.RFC3339),
1316		}
1317		s.NextSeq++
1318		p.Seq = s.NextSeq
1319		s.Payments[payID] = p
1320	
1321		// 收款记录、序号与余额状态在同一次原子保存中持久化；保存失败则
1322		// 一切不生效，该收款标识不被占用。
1323		if err := s.save(); err != nil {
1324			delete(s.Payments, payID)
1325			s.NextSeq--
1326			return err
1327		}
1328		fmt.Fprintf(stdout, "已登记收款 %q（总额 %d 分，%s）：\n", payID, total, moneyFen(total))
1329		printAllocationBalances(s, p, allocs)
1330		fmt.Fprintln(stdout)
1331		printPayment(p, s)
1332		return nil
1333	}
1334	
1335	// samePaymentContent 按客户、总额、备注与月份-金额对应关系判定两笔收款
1336	// 内容相同；分配顺序不影响身份。判重依据首次登记内容，不受后续更正影响。
1337	func samePaymentContent(p *payment, customerID string, total int64, note string, allocs []paymentAllocation) bool {
1338		if p.CustomerID != customerID || p.Total != total || p.Note != note {
1339			return false
1340		}
1341		return sameAllocations(p.Allocations, allocs)
1342	}
1343	
1344	// sameAllocations 判定两个分配列表的月份-金额对应关系相同（顺序无关）。
1345	func sameAllocations(a, b []paymentAllocation) bool {
1346		if len(a) != len(b) {
1347			return false
1348		}
1349		for _, al := range b {
1350			if allocAmountFor(a, al.Month) != al.Amount {
1351				return false
1352			}
1353		}
1354		return true
1355	}
1356	
1357	// formatAllocations 以 "2026-09:500,2026-10:300" 形式展示分配列表。
1358	func formatAllocations(allocs []paymentAllocation) string {
1359		parts := make([]string, len(allocs))
1360		for i, al := range allocs {
1361			parts[i] = fmt.Sprintf("%s:%d", al.Month, al.Amount)
1362		}
1363		return strings.Join(parts, ",")
1364	}
