1377	func cmdBillUnpay(dir, payID, reason string) error {
1378		if strings.TrimSpace(payID) == "" {
1379			return fmt.Errorf("收款标识不能为空")
1380		}
1381		if strings.TrimSpace(reason) == "" {
1382			return fmt.Errorf("撤销原因不能为空")
1383		}
1384	
1385		s, err := loadStore(dir)
1386		if err != nil {
1387			return err
1388		}
1389		p, ok := s.Payments[payID]
1390		if !ok {
1391			return fmt.Errorf("收款标识 %q 不存在，无法撤销", payID)
1392		}
1393	
1394		if p.Revoked {
1395			// 相同标识与相同原因重复撤销：幂等成功，不新增历史；
1396			// 改用其他原因则拒绝。
1397			if p.RevokeReason == reason {
1398				fmt.Fprintf(stdout, "收款 %q 已撤销且撤销原因相同，幂等返回（不新增历史）：\n\n", payID)
1399				printPayment(p, s)
1400				return nil
1401			}
1402			return fmt.Errorf("收款 %q 已撤销（撤销原因 %q），改用其他原因重复撤销被拒绝", payID, p.RevokeReason)
1403		}
1404	
1405		// 首次退款后该收款的最新分配固定，拒绝整笔撤销；退款记录永久保留且
1406		// 不可撤销，实收按扣除退款后的余额继续计算。无退款的收款仍按原规则
1407		// 处理。
1408		if paymentHasRefunds(s, payID) {
1409			return fmt.Errorf("收款 %q 已发生退款，最新分配已固定，拒绝整笔撤销；如需退回余款请继续登记部分退款", payID)
1410		}
1411	
1412		// 撤销整笔生效：取消该笔在全部分配月份上的最新实收（经更正的以最新
1413		// 分配为准），不接受部分撤销；不改变应付、其他收款或调整，原收款、
1414		// 分配、更正与撤销原因永久保留。
1415		p.Revoked = true
1416		p.RevokeReason = reason
1417		p.RevokedAt = time.Now().UTC().Format(time.RFC3339)
1418		s.NextSeq++
1419		p.RevokeSeq = s.NextSeq
1420	
1421		// 撤销信息与原记录在同一次原子保存中持久化；保存失败则一切不生效。
1422		if err := s.save(); err != nil {
1423			p.Revoked = false
1424			p.RevokeReason = ""
1425			p.RevokedAt = ""
1426			p.RevokeSeq = 0
1427			s.NextSeq--
1428			return err
1429		}
1430		fmt.Fprintf(stdout, "已撤销收款 %q（总额 %d 分，%s），取消最新分配：\n", payID, p.Total, moneyFen(p.Total))
1431		printAllocationBalances(s, p, currentAllocations(s, p))
1432		fmt.Fprintln(stdout)
1433		printPayment(p, s)
1434		return nil
1435	}
1436	
1437	// printPayment 输出单笔收款记录：总额、首次登记的全部分配（永久保留，
1438	// 判重依据）与当前状态；经历过更正时同时展示当前生效的最新分配。
1439	// 各月应付/实收取自当前库状态。
1440	func printPayment(p *payment, s *state) {
1441		fmt.Fprintf(stdout, "收款标识：%s\n", p.ID)
1442		fmt.Fprintf(stdout, "客户：%s\n", p.CustomerID)
1443		fmt.Fprintf(stdout, "收款总额：%d 分（%s）\n", p.Total, moneyFen(p.Total))
1444		fmt.Fprintf(stdout, "备注：%s\n", p.Note)
1445		if p.Revoked {
1446			fmt.Fprintf(stdout, "当前状态：已撤销（撤销原因：%s）\n", p.RevokeReason)
1447		} else {
1448			fmt.Fprintf(stdout, "当前状态：实收中\n")
1449		}
1450		fmt.Fprintln(stdout, "分配明细（首次登记，永久保留）：")
1451		for i, al := range p.Allocations {
1452			b := s.Bills[billKey(p.CustomerID, al.Month)] // 载入时已校验存在
1453			_, payable, _ := billTotals(b, adjustmentsFor(s, p.CustomerID, al.Month))
1454			received, _ := paymentReceived(s, p.CustomerID, al.Month)
1455			fmt.Fprintf(stdout, "  %d. 月份 %s：分配 %d 分（%s）；当前应付 %d 分，实收合计 %d 分，未收余额 %d 分\n",
1456				i+1, al.Month, al.Amount, moneyFen(al.Amount), payable, received, payable-received)
1457		}
1458		if corrs := correctionsFor(s, p.ID); len(corrs) > 0 {
1459			fmt.Fprintf(stdout, "当前分配（经 %d 次更正，以最新为准）：%s\n",
1460				len(corrs), formatAllocations(currentAllocations(s, p)))
1461		}
1462		if refs := refundsFor(s, p.ID); len(refs) > 0 {
1463			current := currentAllocations(s, p)
1464			fmt.Fprintf(stdout, "退款记录（%d 笔，永久保留、不可撤销；首次退款后最新分配已固定）：\n", len(refs))
1465			for _, r := range refs {
1466				fmt.Fprintf(stdout, "  退款 %s：%s，原因：%s\n", r.ID, formatAllocations(r.Allocations), r.Reason)
1467			}
1468			fmt.Fprintln(stdout, "各月剩余可退额（最新分配减累计退款）：")
1469			for _, al := range current {
1470				refunded := refundedForMonth(s, p.ID, al.Month)
1471				fmt.Fprintf(stdout, "  月份 %s：分配 %d 分，累计已退 %d 分，剩余可退 %d 分（%s）\n",
1472					al.Month, al.Amount, refunded, al.Amount-refunded, moneyFen(al.Amount-refunded))
1473			}
1474		}
1475	}
