func TestUsageCorrectLoadValidation(t *testing.T) {
	// 合法存档可读，show 展示关联。
	h := newHarness(t)
	if err := os.WriteFile(h.statePath(), []byte(validCorrectionState), 0o644); err != nil {
		t.Fatal(err)
	}
	out := h.mustRun("usage", "show", "u2")
	if !strings.Contains(out, "直接前身：u1") || !strings.Contains(out, "记错了") {
		t.Fatal(out)
	}

	const corr = `"usage_corrections": {"u1": {"usage_id": "u1", "replacement_id": "u2", "new_customer_id": "c1", "new_time": "2026-09-16T10:00:00Z", "new_quantity": 5, "reason": "记错了", "created_at": "2026-09-20T00:00:00Z"}}`
	cases := map[string]string{
		"关联引用替代缺失": `"usage": {
    "u1": {"id": "u1", "customer_id": "c1", "time": "2026-09-15T10:00:00Z", "quantity": 2}
  },
  "bills": {},
  "withdrawals": {"u1": {"usage_id": "u1", "reason": "记错了", "created_at": "2026-09-20T00:00:00Z"}},
  "usage_corrections": {"u1": {"usage_id": "u1", "replacement_id": "u2", "new_customer_id": "c1", "new_time": "2026-09-16T10:00:00Z", "new_quantity": 5, "reason": "记错了", "created_at": "2026-09-20T00:00:00Z"}}`,
		"关联引用原记录缺失": `"usage": {
    "u2": {"id": "u2", "customer_id": "c1", "time": "2026-09-16T10:00:00Z", "quantity": 5}
  },
  "bills": {},
  "usage_corrections": {"u1": {"usage_id": "u1", "replacement_id": "u2", "new_customer_id": "c1", "new_time": "2026-09-16T10:00:00Z", "new_quantity": 5, "reason": "记错了", "created_at": "2026-09-20T00:00:00Z"}}`,
		"原记录未撤回":     `"withdrawals": {},
  "usage_corrections": {"u1": {"usage_id": "u1", "replacement_id": "u2", "new_customer_id": "c1", "new_time": "2026-09-16T10:00:00Z", "new_quantity": 5, "reason": "记错了", "created_at": "2026-09-20T00:00:00Z"}}`,
		"撤回原因不符":     `"withdrawals": {"u1": {"usage_id": "u1", "reason": "别的原因", "created_at": "2026-09-20T00:00:00Z"}},
  "usage_corrections": {"u1": {"usage_id": "u1", "replacement_id": "u2", "new_customer_id": "c1", "new_time": "2026-09-16T10:00:00Z", "new_quantity": 5, "reason": "记错了", "created_at": "2026-09-20T00:00:00Z"}}`,
		"替代内容不符":     `"usage_corrections": {"u1": {"usage_id": "u1", "replacement_id": "u2", "new_customer_id": "c1", "new_time": "2026-09-16T10:00:00Z", "new_quantity": 9, "reason": "记错了", "created_at": "2026-09-20T00:00:00Z"}}`,
		"新客户不存在":     `"usage_corrections": {"u1": {"usage_id": "u1", "replacement_id": "u2", "new_customer_id": "c9", "new_time": "2026-09-16T10:00:00Z", "new_quantity": 5, "reason": "记错了", "created_at": "2026-09-20T00:00:00Z"}}`,
		"更正原因为空":     `"usage_corrections": {"u1": {"usage_id": "u1", "replacement_id": "u2", "new_customer_id": "c1", "new_time": "2026-09-16T10:00:00Z", "new_quantity": 5, "reason": " ", "created_at": "2026-09-20T00:00:00Z"}}`,
		"更正键不一致":     `"usage_corrections": {"ux": {"usage_id": "u1", "replacement_id": "u2", "new_customer_id": "c1", "new_time": "2026-09-16T10:00:00Z", "new_quantity": 5, "reason": "记错了", "created_at": "2026-09-20T00:00:00Z"}}`,
		"更正记录为空":     `"usage_corrections": {"u1": null}`,
	}
	for name, replacement := range cases {
		h := newHarness(t)
		broken := strings.Replace(validCorrectionState, corr, replacement, 1)
		if broken == validCorrectionState {
			t.Fatalf("%s：替换未生效", name)
		}
		if err := os.WriteFile(h.statePath(), []byte(broken), 0o644); err != nil {
			t.Fatal(err)
		}
		msg := h.runExpectErr("usage", "show", "u1")
		if !strings.Contains(msg, "损坏") {
			t.Fatalf("%s：应按损坏拒绝: %s", name, msg)
		}
		got, _ := os.ReadFile(h.statePath())
		if string(got) != broken {
			t.Fatalf("%s：损坏文件被改写", name)
		}
	}
}

